class VotingSystem:
    def __init__(self):
        self.candidates = {}

    def cast_vote(self, candidate):
        if candidate in self.candidates:
            self.candidates[candidate] += 1
        else:
            self.candidates[candidate] = 1

    def get_vote_count(self, candidate):
        return self.candidates.get(candidate, 0)

