import pandas as pd

class InvestmentManager:
    def __init__(self, investments):
        self.investments = investments

    def filter_investments(self, risk_level=None, return_rate=None):
        filtered = self.investments
        if risk_level:
            filtered = filtered.filter(lambda x: x['risk'] == risk_level, axis=0)
        if return_rate:
            filtered = filtered.filter(lambda x: x['return_rate'] >= return_rate, axis=0)
        return filtered

    def sort_investments(self, by='return_rate', ascending=True):
        return self.investments.sort_values(by=by, ascending=ascending)

