class TransactionEvent:
    def __init__(self, transaction_id: str, channel: str, amount: float, timestamp: datetime):
        self.transaction_id = transaction_id
        self.channel = channel
        self.amount = amount
        self.timestamp = timestamp

    def __repr__(self):
        return f"TransactionEvent(transaction_id={self.transaction_id}, channel={self.channel}, amount={self.amount}, timestamp={self.timestamp})"

class CrossChannelTransactionManager:
    def __init__(self):
        self.transactions: Dict[str, List[TransactionEvent]] = {}

    def add_transaction(self, transaction: TransactionEvent):
        if transaction.channel not in self.transactions:
            self.transactions[transaction.channel] = []
        self.transactions[transaction.channel].append(transaction)

    def get_transactions_by_channel(self, channel: str) -> List[TransactionEvent]:
        return self.transactions.get(channel, [])

    def get_all_transactions(self) -> List[TransactionEvent]:
        all_transactions = []
        for transactions in self.transactions.values():
            all_transactions.extend(transactions)
        return all_transactions

