import re

class InsuranceClaimManager:
    def __init__(self):
        self.claims = {}
        self.claim_id_pattern = re.compile(r'^[A-Za-z0-9]{8,16}$')

    def validate_claim_id(self, claim_id):
        return self.claim_id_pattern.match(claim_id) is not None

    def add_claim(self, claim_id, claim_data):
        if not self.validate_claim_id(claim_id):
            raise ValueError("Invalid claim ID. ID must be alphanumeric and 8-16 characters long.")
        self.claims[claim_id] = claim_data

    def get_claim(self, claim_id):
        return self.claims.get(claim_id, None)

    def update_claim(self, claim_id, claim_data):
        if claim_id not in self.claims:
            raise KeyError("Claim ID not found.")
        self.claims[claim_id] = claim_data

    def delete_claim(self, claim_id):
        if claim_id not in self.claims:
            raise KeyError("Claim ID not found.")
        del self.claims[claim_id]

