class MoneyTransfer:
    def __init__(self):
        self.accounts = {}

    def add_account(self, account_number, balance):
        if account_number in self.accounts:
            raise ValueError("Account number already exists.")
        self.accounts[account_number] = balance

    def transfer(self, sender_account, receiver_account, amount):
        if sender_account not in self.accounts or receiver_account not in self.accounts:
            raise ValueError("Invalid account number.")
        if self.accounts[sender_account] < amount:
            raise ValueError("Insufficient funds.")

        self.accounts[sender_account] -= amount
        self.accounts[receiver_account] += amount
        print(f"Transfer successful: {amount} from {sender_account} to {receiver_account}")

