from contextlib import contextmanager
from abc import ABC, abstractmethod

class BlockchainInterface(ABC):
    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def disconnect(self):
        pass

    @abstractmethod
    def execute_contract(self, contract_code):
        pass

class EthereumInterface(BlockchainInterface):
    def connect(self):
        print("Connecting to Ethereum network")

    def disconnect(self):
        print("Disconnecting from Ethereum network")

    def execute_contract(self, contract_code):
        print(f"Executing contract on Ethereum: {contract_code}")

class BinanceSmartChainInterface(BlockchainInterface):
    def connect(self):
        print("Connecting to Binance Smart Chain network")

    def disconnect(self):
        print("Disconnecting from Binance Smart Chain network")

    def execute_contract(self, contract_code):
        print(f"Executing contract on Binance Smart Chain: {contract_code}")

class BlockchainManager:
    def __init__(self):
        self.interfaces = {}

    def register_interface(self, name, interface):
        self.interfaces[name] = interface

    @contextmanager
    def use_interface(self, name):
        interface = self.interfaces.get(name)
        if interface:
            interface.connect()
            try:
                yield interface
            finally:
                interface.disconnect()
        else:
            raise ValueError(f"Interface {name} not registered")

# Example usage
manager = BlockchainManager()
manager.register_interface('ethereum', EthereumInterface())
manager.register_interface('bsc', BinanceSmartChainInterface())

with manager.use_interface('ethereum') as eth_interface:
    eth_interface.execute_contract("0x1234...")

with manager.use_interface('bsc') as bsc_interface:
    bsc_interface.execute_contract("0x5678...")

