class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def append(self, transaction_id, timestamp, amount, sender, receiver):
        new_node = TransactionNode(transaction_id, timestamp, amount, sender, receiver)
        if not self.head:
            self.head = self.tail = new_node
        else:
            new_node.prev = self.tail
            self.tail.next = new_node
            self.tail = new_node

    def delete(self, transaction_id):
        current = self.head
        while current:
            if current.transaction_id == transaction_id:
                if current.prev:
                    current.prev.next = current.next
                else:
                    self.head = current.next
                if current.next:
                    current.next.prev = current.prev
                else:
                    self.tail = current.prev
                return
            current = current.next

    def get_transaction(self, transaction_id):
        current = self.head
        while current:
            if current.transaction_id == transaction_id:
                return current
            current = current.next
        return None

    def traverse(self):
        current = self.head
        while current:
            print(f"Transaction ID: {current.transaction_id}, Timestamp: {current.timestamp}, Amount: {current.amount}, Sender: {current.sender}, Receiver: {current.receiver}")
            current = current.next

# Example usage:
