import re

class PolicyMeta(type):
    def __new__(cls, name, bases, dct):
        # Validate attributes
        for attr, value in dct.items():
            if isinstance(value, str):
                if not re.match(r'^[A-Za-z0-9\s\-]+$', value):
                    raise ValueError(f"Invalid attribute value for {attr}: {value}")

        # Validate methods
        for method_name, method in dct.items():
            if callable(method):
                if not re.match(r'^[a-zA-Z0-9_]+$', method_name):
                    raise ValueError(f"Invalid method name: {method_name}")

        return super().__new__(cls, name, bases, dct)

class UnderwritingPolicy(metaclass=PolicyMeta):
    policy_name = "Standard Life Policy"
    policy_number = "123456789"
    policy_holder = "John Doe"
