class AccountManager:
    def __init__(self):
        self.accounts = {}

    def create_account(self, account_id, initial_balance=0):
        if account_id in self.accounts:
            raise ValueError("Account already exists")
        self.accounts[account_id] = {
            'balance': initial_balance,
            'transactions': []
        }

    def deposit(self, account_id, amount):
        if account_id not in self.accounts:
            raise ValueError("Account does not exist")
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self.accounts[account_id]['balance'] += amount
        self.accounts[account_id]['transactions'].append(f"Deposited {amount}")

    def withdraw(self, account_id, amount):
        if account_id not in self.accounts:
            raise ValueError("Account does not exist")
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if self.accounts[account_id]['balance'] < amount:
            raise ValueError("Insufficient funds")
        self.accounts[account_id]['balance'] -= amount
        self.accounts[account_id]['transactions'].append(f"Withdrew {amount}")

    def transfer(self, from_account_id, to_account_id, amount):
        if from_account_id not in self.accounts or to_account_id not in self.accounts:
            raise ValueError("One or both accounts do not exist")
        if amount <= 0:
            raise ValueError("Transfer amount must be positive")
        if self.accounts[from_account_id]['balance'] < amount:
            raise ValueError("Insufficient funds")
        self.accounts[from_account_id]['balance'] -= amount
        self.accounts[from_account_id]['transactions'].append(f"Transferred {amount} to {to_account_id}")
        self.accounts[to_account_id]['balance'] += amount
        self.accounts[to_account_id]['transactions'].append(f"Received {amount} from {from_account_id}")

    def get_account_summary(self, account_id):
        if account_id not in self.accounts:
            raise ValueError("Account does not exist")
        summary = {
            'balance': self.accounts[account_id]['balance'],
            'transactions': self.accounts[account_id]['transactions']
        }
        return summary

# Example usage
account_manager = AccountManager()
account_manager.create_account("12345", 1000)
account_manager.deposit("12345", 500)
account_manager.withdraw("12345", 200)
account_manager.transfer("12345", "67890", 300)
print(account_manager.get_account_summary("12345"))
print(account_manager.get_account_summary("67890"))

from datetime import datetime

class Transaction:
    def __init__(self, amount, description, date):
        self.amount = amount
        self.description = description
        self.date = date

    def __repr__(self):
        return f"Transaction(amount={self.amount}, description={self.description}, date={self.date})"

class TransactionHistory:
    def __init__(self):
        self.transactions = {}

    def add_transaction(self, transaction):
        month = transaction.date.strftime('%Y-%m')
        if month not in self.transactions:
            self.transactions[month] = []
        self.transactions[month].append(transaction)

    def get_transactions(self, month):
        month = month.strftime('%Y-%m') if isinstance(month, datetime) else month
        return self.transactions.get(month, [])

    def calculate_monthly_spending(self, month):
        month = month.strftime('%Y-%m') if isinstance(month, datetime) else month
        return sum(transaction.amount for transaction in self.transactions.get(month, []))

# Example usage:
