import datetime
import hashlib
from dataclasses import dataclass, field
from typing import List

class TransactionValidationError(Exception):
    pass

@dataclass
class FinancialTransaction:
    transaction_id: str
    timestamp: datetime.datetime
    amount: float
    account_number: str
    counterparty: str
    hash_value: str = field(init=False)

    def __post_init__(self):
        self.hash_value = self.calculate_hash()

    def calculate_hash(self) -> str:
        data = f"{self.transaction_id}{self.timestamp}{self.amount}{self.account_number}{self.counterparty}"
        return hashlib.sha256(data.encode()).hexdigest()

    def validate(self) -> None:
        if not self.transaction_id:
            raise TransactionValidationError("Transaction ID cannot be empty")
        if not self.timestamp:
            raise TransactionValidationError("Timestamp cannot be empty")
        if self.amount <= 0:
            raise TransactionValidationError("Amount must be greater than zero")
        if not self.account_number:
            raise TransactionValidationError("Account number cannot be empty")
        if not self.counterparty:
            raise TransactionValidationError("Counterparty cannot be empty")

@dataclass
class RegulatoryReport:
    transactions: List[FinancialTransaction]

    def validate_transactions(self) -> None:
        for transaction in self.transactions:
            transaction.validate()

# Example usage
transactions = [
    FinancialTransaction(
        transaction_id="TX12345",
        timestamp=datetime.datetime(2023, 10, 1, 12, 0, 0),
        amount=1000.0,
        account_number="1234-5678-9012-3456",
        counterparty="CounterpartyA"
    ),
    FinancialTransaction(
        transaction_id="TX67890",
        timestamp=datetime.datetime(2023, 10, 2, 12, 0, 0),
        amount=2000.0,
        account_number="9876-5432-1098-7654",
        counterparty="CounterpartyB"
    )
]

report = RegulatoryReport(transactions=transactions)
report.validate_transactions()

