class FungibleTokenTransaction:
    def __init__(self, token_id, amount):
        self.token_id = token_id
        self.amount = amount

    @staticmethod
    def is_valid_token_id(token_id):
        # Regular expression pattern for token ID validation
        pattern = r'^[a-zA-Z0-9]{1,}$'
        return re.match(pattern, token_id) is not None

    def validate(self):
        if not self.is_valid_token_id(self.token_id):
            raise ValueError(f"Invalid token ID: {self.token_id}")
        if self.amount <= 0:
            raise ValueError(f"Invalid amount: {self.amount}")

    def parse(self):
        self.validate()
        return f"Token ID: {self.token_id}, Amount: {self.amount}"

