import cachetools

class CustomerRiskProfileManager:
    def __init__(self, max_cache_size=1000):
        self.risk_profiles = {}
        self.cache = cachetools.TTLCache(maxsize=max_cache_size, ttl=300)

    def add_customer(self, customer_id, risk_profile):
        if customer_id in self.risk_profiles:
            raise ValueError(f"Customer with ID {customer_id} already exists.")
        self.risk_profiles[customer_id] = risk_profile
        self.cache[customer_id] = risk_profile

    def update_customer(self, customer_id, risk_profile):
        if customer_id not in self.risk_profiles:
            raise ValueError(f"Customer with ID {customer_id} does not exist.")
        self.risk_profiles[customer_id] = risk_profile
        self.cache[customer_id] = risk_profile

    def remove_customer(self, customer_id):
        if customer_id not in self.risk_profiles:
            raise ValueError(f"Customer with ID {customer_id} does not exist.")
        del self.risk_profiles[customer_id]
        del self.cache[customer_id]

    def get_customer_risk_profile(self, customer_id):
        if customer_id in self.cache:
            return self.cache[customer_id]
        elif customer_id in self.risk_profiles:
            self.cache[customer_id] = self.risk_profiles[customer_id]
            return self.risk_profiles[customer_id]
        else:
            raise ValueError(f"Customer with ID {customer_id} does not exist.")

