def calculate_sma(closing_prices, window):
    sma = []
    for i in range(len(closing_prices)):
        if i < window - 1:
            sma.append(None)
        else:
            window_sum = sum(closing_prices[i - window + 1:i + 1])
            sma.append(window_sum / window)
    return sma

