import pandas as pd
from datetime import datetime

class ATMTransactionProcessor:
    def __init__(self):
        self.transactions = pd.DataFrame(columns=['transaction_id', 'account_number', 'transaction_type', 'amount', 'timestamp', 'balance'])

    def process_transaction(self, account_number, transaction_type, amount):
        if transaction_type not in ['deposit', 'withdrawal', 'balance_inquiry']:
            raise ValueError("Invalid transaction type")

        if transaction_type == 'withdrawal' and amount > self.get_balance(account_number):
            raise ValueError("Insufficient balance")

        transaction_id = self.transactions.shape[0] + 1
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        new_balance = self.get_balance(account_number) + (amount if transaction_type == 'deposit' else -amount)

        new_transaction = pd.DataFrame({
            'transaction_id': [transaction_id],
            'account_number': [account_number],
            'transaction_type': [transaction_type],
            'amount': [amount],
            'timestamp': [timestamp],
            'balance': [new_balance]
        })

        self.transactions = pd.concat([self.transactions, new_transaction], ignore_index=True)
        return new_balance

    def get_balance(self, account_number):
        if account_number not in self.transactions['account_number'].values:
            return 0
        return self.transactions[self.transactions['account_number'] == account_number]['balance'].iloc[-1]

    def generate_report(self, account_number):
        account_transactions = self.transactions[self.transactions['account_number'] == account_number]
        report = account_transactions[['timestamp', 'transaction_type', 'amount', 'balance']]
        return report

