from cryptography.fernet import Fernet

class PrivacyPreservingSmartContract:
    def __init__(self, key=None):
        if key is None:
            self.key = Fernet.generate_key()
        else:
            self.key = key
        self.cipher_suite = Fernet(self.key)

    def encrypt_data(self, data):
        return self.cipher_suite.encrypt(data.encode())

    def decrypt_data(self, encrypted_data):
        return self.cipher_suite.decrypt(encrypted_data).decode()

    def secure_aggregate(self, encrypted_data_list):
        decrypted_data_list = [self.decrypt_data(data) for data in encrypted_data_list]
        aggregated_data = sum(int(data) for data in decrypted_data_list)
        return self.encrypt_data(str(aggregated_data))

# Example usage:
contract = PrivacyPreservingSmartContract()
data1 = "10"
data2 = "20"

encrypted_data1 = contract.encrypt_data(data1)
encrypted_data2 = contract.encrypt_data(data2)

encrypted_aggregated_data = contract.secure_aggregate([encrypted_data1, encrypted_data2])
print("Encrypted Aggregated Data:", encrypted_aggregated_data)

decrypted_aggregated_data = contract.decrypt_data(encrypted_aggregated_data)
print("Decrypted Aggregated Data:", decrypted_aggregated_data)

