class DocumentUploader:
    def __init__(self, upload_dir: str):
        self.upload_dir = upload_dir
        if not os.path.exists(upload_dir):
            os.makedirs(upload_dir)

    def upload_documents(self, documents: List[BytesIO]) -> List[str]:
        uploaded_files = []
        for doc in documents:
            with NamedTemporaryFile(delete=False, dir=self.upload_dir, suffix='.tmp') as temp_file:
                shutil.copyfileobj(doc, temp_file)
                uploaded_files.append(temp_file.name)
        return uploaded_files

    def retrieve_document(self, file_path: str) -> BytesIO:
        with open(file_path, 'rb') as file:
            return BytesIO(file.read())

    def delete_document(self, file_path: str) -> None:
        os.remove(file_path)

