class TradingPlatform:
    def __init__(self):
        self.orders = {}

    def place_order(self, order_id, symbol, quantity, price, order_type):
        if order_id in self.orders:
            raise ValueError("Order ID already exists")
        self.orders[order_id] = {
            "symbol": symbol,
            "quantity": quantity,
            "price": price,
            "order_type": order_type,
            "status": "Open"
        }
        return f"Order {order_id} placed successfully."

    def cancel_order(self, order_id):
        if order_id not in self.orders:
            raise ValueError("Order ID does not exist")
        if self.orders[order_id]["status"] == "Closed":
            raise ValueError("Order is already closed")
        self.orders[order_id]["status"] = "Closed"
        return f"Order {order_id} canceled successfully."

    def update_order(self, order_id, quantity=None, price=None):
        if order_id not in self.orders:
            raise ValueError("Order ID does not exist")
        if self.orders[order_id]["status"] == "Closed":
            raise ValueError("Order is already closed")
        if quantity is not None:
            self.orders[order_id]["quantity"] = quantity
        if price is not None:
            self.orders[order_id]["price"] = price
        return f"Order {order_id} updated successfully."

    def simulate_trade_execution(self, order_id, market_price):
        if order_id not in self.orders:
            raise ValueError("Order ID does not exist")
        if self.orders[order_id]["status"] == "Closed":
            raise ValueError("Order is already closed")
        if self.orders[order_id]["order_type"] == "Buy":
            if market_price <= self.orders[order_id]["price"]:
                self.orders[order_id]["status"] = "Closed"
                return f"Order {order_id} executed at market price {market_price}."
            else:
                return f"Order {order_id} not executed. Market price {market_price} is higher than order price {self.orders[order_id]['price']}."
        elif self.orders[order_id]["order_type"] == "Sell":
            if market_price >= self.orders[order_id]["price"]:
                self.orders[order_id]["status"] = "Closed"
                return f"Order {order_id} executed at market price {market_price}."
            else:
                return f"Order {order_id} not executed. Market price {market_price} is lower than order price {self.orders[order_id]['price']}."
        else:
            raise ValueError("Invalid order type")

