class PolicyClaimsManager:
    def __init__(self):
        self.claims = {}

    def add_claim(self, claim):
        if claim.policy_number not in self.claims:
            self.claims[claim.policy_number] = []
        self.claims[claim.policy_number].append(claim)

    def update_claim(self, claim_id, new_amount, new_status):
        for policy_claims in self.claims.values():
            for claim in policy_claims:
                if claim.claim_id == claim_id:
                    claim.claim_amount = new_amount
                    claim.claim_status = new_status
                    return
        raise ValueError("Claim not found")

    def get_claim(self, claim_id):
        for policy_claims in self.claims.values():
            for claim in policy_claims:
                if claim.claim_id == claim_id:
                    return claim
        raise ValueError("Claim not found")

    def get_total_claim_amount(self, policy_number):
        return sum(claim.claim_amount for claim in self.claims.get(policy_number, []))

    def generate_summary_report(self, policy_number):
        claims = self.claims.get(policy_number, [])
        num_claims = len(claims)
        total_claim_amount = self.get_total_claim_amount(policy_number)
        average_claim_amount = total_claim_amount / num_claims if num_claims > 0 else 0
        return {
            "policy_number": policy_number,
            "num_claims": num_claims,
            "total_claim_amount": total_claim_amount,
            "average_claim_amount": average_claim_amount
        }

