        with self.session() as session:
            url = f"{self.base_url}/policies/{policy_id}"
            response = session.put(url, json=updates)
            response.raise_for_status()
            return response.json()

    def list_policies(self, customer_id: str) -> Dict[str, Any]:
        with self.session() as session:
            url = f"{self.base_url}/customers/{customer_id}/policies"
