from abc import ABC, abstractmethod

class FraudPreventionMeta(type):
    def __new__(cls, name, bases, dct):
        if not all(issubclass(base, ABC) for base in bases):
            raise TypeError("All bases must be abstract base classes")
        if not all(hasattr(base, 'authenticate') for base in bases):
            raise TypeError("All bases must implement the 'authenticate' method")
        if not all(hasattr(base, 'manage_session') for base in bases):
            raise TypeError("All bases must implement the 'manage_session' method")
        if not all(hasattr(base, 'detect_anomaly') for base in bases):
            raise TypeError("All bases must implement the 'detect_anomaly' method")
        return super().__new__(cls, name, bases, dct)

class FraudPreventionABC(ABC, metaclass=FraudPreventionMeta):
    @abstractmethod
    def authenticate(self, user_id, credentials):
        pass

    @abstractmethod
    def manage_session(self, session_id):
        pass

    @abstractmethod
    def detect_anomaly(self, transaction_data):
        pass

