import abc

class TaxModel(metaclass=abc.ABCMeta):
    @abc.abstractmethod
    def calculate_tax(self, income):
        pass

class FlatTaxModel(TaxModel):
    def __init__(self, tax_rate):
        self.tax_rate = tax_rate

    def calculate_tax(self, income):
        return income * self.tax_rate

class ProgressiveTaxModel(TaxModel):
    def __init__(self, brackets):
        self.brackets = brackets

    def calculate_tax(self, income):
        tax = 0
        for bracket in self.brackets:
            if income > bracket['max_income']:
                tax += (bracket['max_income'] - bracket['min_income']) * bracket['rate']
            else:
                tax += (income - bracket['min_income']) * bracket['rate']
                break
        return tax

