class FraudAlertSystem:
    def __init__(self, threshold=50):
        self.transactions = []
        self.threshold = threshold

    def add_transaction(self, transaction):
        self.transactions.append(transaction)
        if self.check_suspicious(transaction):
            self.trigger_alert(transaction)

    def check_suspicious(self, transaction):
        score = 0
        # Simple scoring system example: high value transactions are more suspicious
        if transaction['amount'] > 1000:
            score += 20
        # High frequency transactions are more suspicious
        if transaction['frequency'] > 10:
            score += 10
        # Suspicious activity codes
        if transaction['activity_code'] in ['R', 'S']:
            score += 30
        return score > self.threshold

    def trigger_alert(self, transaction):
        print(f"Suspected fraudulent transaction: {transaction}")

