class GovernanceMechanism:
    def __init__(self):
        self.users = {}
        self.proposals = {}
        self.votes = {}

    def authorize_user(self, user_id, is_authorized):
        self.users[user_id] = is_authorized

    def create_proposal(self, proposal_id, user_id, details):
        if self.users[user_id]:
            self.proposals[proposal_id] = {'details': details, 'votes': {}}
        else:
            raise Exception("User is not authorized to create a proposal.")

    def vote_on_proposal(self, proposal_id, user_id, vote):
        if proposal_id in self.proposals and user_id in self.users:
            if user_id not in self.votes[proposal_id]:
                self.votes[proposal_id][user_id] = vote
            else:
                raise Exception("User has already voted on this proposal.")
        else:
            raise Exception("Invalid proposal ID or user ID.")

    def make_decision(self, proposal_id):
        if proposal_id in self.proposals:
            votes = self.votes[proposal_id]
            total_votes = len(votes)
            yes_votes = sum(1 for vote in votes.values() if vote == 'yes')
            no_votes = total_votes - yes_votes
            if yes_votes > no_votes:
                return "Proposal accepted"
            elif no_votes > yes_votes:
                return "Proposal rejected"
            else:
                return "Proposal tied"
        else:
            raise Exception("Invalid proposal ID.")

