        self.transaction_count = 0

    def add_transaction(self, transaction_id, amount):
        if self.transaction_count < len(self.transactions):
            self.transactions[self.transaction_count] = (transaction_id, amount)
            self.transaction_count += 1
        else:
            raise MemoryError("Transaction array is full, cannot add more transactions.")

