import typing
import hashlib
import pickle

class NFTManager:
    def __init__(self):
        self.nfts = {}

    def add_nft(self, token_id: str, owner_address: str, metadata: dict):
        if token_id in self.nfts:
            raise ValueError(f"Token ID {token_id} already exists")
        self.nfts[token_id] = {
            'owner': owner_address,
            'metadata': self._hash_metadata(metadata)
        }

    def remove_nft(self, token_id: str):
        if token_id not in self.nfts:
            raise ValueError(f"Token ID {token_id} does not exist")
        del self.nfts[token_id]

    def update_nft(self, token_id: str, owner_address: typing.Optional[str] = None, metadata: typing.Optional[dict] = None):
        if token_id not in self.nfts:
            raise ValueError(f"Token ID {token_id} does not exist")
        if owner_address is not None:
            self.nfts[token_id]['owner'] = owner_address
        if metadata is not None:
            self.nfts[token_id]['metadata'] = self._hash_metadata(metadata)

    def get_nft(self, token_id: str):
        if token_id not in self.nfts:
            raise ValueError(f"Token ID {token_id} does not exist")
        return self.nfts[token_id]

    def query_nfts(self, owner_address: typing.Optional[str] = None, metadata_hash: typing.Optional[str] = None):
        results = []
        for token_id, nft in self.nfts.items():
            if owner_address is not None and nft['owner'] != owner_address:
                continue
            if metadata_hash is not None and nft['metadata'] != metadata_hash:
                continue
            results.append((token_id, nft['owner'], nft['metadata']))
        return results

    def _hash_metadata(self, metadata: dict):
        return hashlib.sha256(pickle.dumps(metadata)).hexdigest()

