class VotingSystem:
    def __init__(self):
        self.voters = {}
        self.votes = {}

    def register_voter(self, voter_id, name):
        if voter_id not in self.voters:
            self.voters[voter_id] = name
            self.votes[voter_id] = None
            print(f"Voter {name} registered successfully.")
        else:
            print(f"Voter {name} is already registered.")

    def cast_vote(self, voter_id, choice):
        if voter_id in self.voters:
            if self.votes[voter_id] is None:
                self.votes[voter_id] = choice
                print(f"Vote cast for {choice} by {self.voters[voter_id]}.")
            else:
                print(f"Voter {self.voters[voter_id]} has already voted.")
        else:
            print("Voter ID not found. Please register first.")

    def tally_votes(self):
        results = {}
        for choice in set(self.votes.values()):
            if choice is not None:
                results[choice] = self.votes.values().count(choice)
        print("Vote Tally:")
        for choice, count in results.items():
            print(f"{choice}: {count} votes")
        return results

