            'solana': 'https://solana.example.com'
        }

    def receive_transaction(self, blockchain, transaction_data):
        if blockchain in self.blockchain_urls:
            url = self.blockchain_urls[blockchain]
            response = requests.post(f'{url}/receive', json=transaction_data)
            return response.json()
        else:
            return {'error': 'Blockchain not supported'}, 400

    def send_transaction(self, blockchain, transaction_data):
        if blockchain in self.blockchain_urls:
            url = self.blockchain_urls[blockchain]
            response = requests.post(f'{url}/send', json=transaction_data)
            return response.json()
        else:
            return {'error': 'Blockchain not supported'}, 400

