import re

class BillPaymentMeta(type):
    def __new__(cls, name, bases, dct):
        if 'service_provider' not in dct:
            raise TypeError(f"{name} must define 'service_provider'")

        if 'account_number' not in dct:
            raise TypeError(f"{name} must define 'account_number'")

        if 'amount' not in dct:
            raise TypeError(f"{name} must define 'amount'")

        if 'validate_data' not in dct:
            raise TypeError(f"{name} must define 'validate_data'")

        return super().__new__(cls, name, bases, dct)

class BillPayment(metaclass=BillPaymentMeta):
    def __init__(self, service_provider, account_number, amount):
        self.service_provider = service_provider
        self.account_number = account_number
        self.amount = amount

    def validate_data(self):
        if not self.service_provider:
            raise ValueError("Service provider is required")

        if not re.match(r'^\d{10}$', self.account_number):
            raise ValueError("Account number must be 10 digits")

        if not isinstance(self.amount, (int, float)) or self.amount <= 0:
            raise ValueError("Amount must be a positive number")

        return True

