import numpy as np

class LiquidityPool:
    def __init__(self, token_a, token_b):
        self.token_a = token_a
        self.token_b = token_b
        self.pool_a = np.array([], dtype=np.float64)
        self.pool_b = np.array([], dtype=np.float64)

    def add_liquidity(self, amount_a, amount_b):
        if len(self.pool_a) == 0:
            self.pool_a = np.array([amount_a])
            self.pool_b = np.array([amount_b])
        else:
            self.pool_a = np.append(self.pool_a, amount_a)
            self.pool_b = np.append(self.pool_b, amount_b)

    def remove_liquidity(self, amount_a, amount_b):
        mask_a = np.isin(self.pool_a, amount_a)
        mask_b = np.isin(self.pool_b, amount_b)
        self.pool_a = self.pool_a[~mask_a]
        self.pool_b = self.pool_b[~mask_b]

    def get_price(self):
        if len(self.pool_a) == 0:
            return None
        else:
            return self.pool_b[-1] / self.pool_a[-1]

    def get_balance(self):
        return self.pool_a, self.pool_b

