class LoanForbearanceProcessor:
    def __init__(self, documentation):
        self.documentation = documentation

    def validate_identification(self):
        # Example regex for a simple ID number
        id_regex = r'^\d{3}-\d{2}-\d{4}$'
        return re.match(id_regex, self.documentation['identification'])

    def validate_phone_number(self):
        # Example regex for a simple US phone number
        phone_regex = r'^\(\d{3}\) \d{3}-\d{4}$'
