class LoanPortfolio:
    def __init__(self):
        self.loans = []

    def add_loan(self, loan):
        self.loans.append(loan)

    def remove_loan(self, loan_id):
        self.loans = [loan for loan in self.loans if loan.loan_id != loan_id]

    def update_loan(self, loan_id, **kwargs):
        for loan in self.loans:
            if loan.loan_id == loan_id:
                for key, value in kwargs.items():
                    setattr(loan, key, value)
                break

    def find_loans_by_risk_level(self, risk_level):
        return [loan for loan in self.loans if loan.risk_level == risk_level]

    def find_loans_by_maturity_date(self, start_date, end_date):
        start_date = datetime.strptime(start_date, '%Y-%m-%d')
        end_date = datetime.strptime(end_date, '%Y-%m-%d')
        return [loan for loan in self.loans if start_date <= loan.maturity_date <= end_date]

