class SavingsAccount:
    def __init__(self, initial_balance=0, min_balance=100, transaction_limit=5000):
        self.balance = initial_balance
        self.min_balance = min_balance
        self.transaction_limit = transaction_limit

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Deposited ${amount}. New balance: ${self.balance}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        if 0 < amount <= self.transaction_limit:
            if self.balance - amount >= self.min_balance:
                self.balance -= amount
                print(f"Withdrew ${amount}. New balance: ${self.balance}")
            else:
                print(f"Insufficient funds. Minimum balance required: ${self.min_balance}")
        else:
            print(f"Withdrawal amount must be positive and within the transaction limit of ${self.transaction_limit}.")

    def check_balance(self):
        print(f"Current balance: ${self.balance}")

