class TransactionPreprocessor:
    def __init__(self, threshold, currency_conversion_rate):
        self.threshold = threshold
        self.currency_conversion_rate = currency_conversion_rate

    def preprocess_transactions(self, transactions):
        # Filter out transactions below the threshold
        filtered_transactions = [tx for tx in transactions if tx['amount'] >= self.threshold]

        # Convert currency amounts to a uniform format
        processed_transactions = [{'id': tx['id'], 'amount': tx['amount'] * self.currency_conversion_rate} for tx in filtered_transactions]

        return processed_transactions

import threading
import queue

class TransactionProcessor:
    def __init__(self, num_workers=5):
        self.tasks = queue.Queue()
        self.threads = []
        self.num_workers = num_workers
        self.start_workers()

    def start_workers(self):
        for _ in range(self.num_workers):
            thread = threading.Thread(target=self.worker)
            thread.start()
            self.threads.append(thread)

    def worker(self):
        while True:
            task = self.tasks.get()
            if task is None:
                break
            self.process_task(task)
            self.tasks.task_done()

    def process_task(self, task):
        # Simulate transaction processing
        print(f"Processing transaction: {task}")

    def add_task(self, task):
        self.tasks.put(task)

    def stop(self):
        for _ in range(self.num_workers):
            self.tasks.put(None)
        for thread in self.threads:
            thread.join()

# Example usage
