class VerificationResult:
    def __init__(self, contract_id, result):
        self.contract_id = contract_id
        self.result = result

class VerificationThread(threading.Thread):
    def __init__(self, contract_id, state, verification_function):
        threading.Thread.__init__(self)
        self.contract_id = contract_id
        self.state = state
        self.verification_function = verification_function

    def run(self):
        result = self.verification_function(self.state)
        verification_result = VerificationResult(self.contract_id, result)
        print(f"Verification result for contract {self.contract_id}: {result}")
        return verification_result

