import pandas as pd

class LoanApplicationManager:
    def __init__(self):
        self.applications = pd.DataFrame(columns=['ApplicantID', 'Income', 'CreditScore', 'LoanAmount', 'Status'])

    def add_application(self, applicant_id, income, credit_score, loan_amount):
        new_application = pd.DataFrame({
            'ApplicantID': [applicant_id],
            'Income': [income],
            'CreditScore': [credit_score],
            'LoanAmount': [loan_amount],
            'Status': ['Pending']
        })
        self.applications = pd.concat([self.applications, new_application], ignore_index=True)

    def validate_applicant_data(self, applicant_id):
        applicant_data = self.applications[self.applications['ApplicantID'] == applicant_id]
        if applicant_data.empty:
            return False
        return True

    def calculate_loan_eligibility(self, applicant_id):
        applicant_data = self.applications[self.applications['ApplicantID'] == applicant_id]
        if not self.validate_applicant_data(applicant_id):
            return False

        income = applicant_data['Income'].values[0]
        credit_score = applicant_data['CreditScore'].values[0]
        loan_amount = applicant_data['LoanAmount'].values[0]

        if income < 50000:
            return False
        if credit_score < 650:
            return False
        if loan_amount > income * 5:
            return False

        return True

    def approve_application(self, applicant_id):
        if self.calculate_loan_eligibility(applicant_id):
            self.applications.loc[self.applications['ApplicantID'] == applicant_id, 'Status'] = 'Approved'
            return True
        else:
            self.applications.loc[self.applications['ApplicantID'] == applicant_id, 'Status'] = 'Denied'
            return False

    def generate_summary_report(self):
        approved = self.applications[self.applications['Status'] == 'Approved']
        denied = self.applications[self.applications['Status'] == 'Denied']
        return {
            'Approved Applications': len(approved),
            'Denied Applications': len(denied)
        }

