class LoanPreapproval:
    def __init__(self, income, credit_score, debt_to_income_ratio):
        self.income = income
        self.credit_score = credit_score
        self.debt_to_income_ratio = debt_to_income_ratio

    def calculate_pre_approval_amount(self):
        if self.income <= 0:
            raise ValueError("Income must be a positive number.")
        if self.credit_score < 300 or self.credit_score > 850:
            raise ValueError("Credit score must be between 300 and 850.")
        if self.debt_to_income_ratio < 0 or self.debt_to_income_ratio > 1:
            raise ValueError("Debt-to-income ratio must be between 0 and 1.")

        if self.credit_score >= 700:
            pre_approval_factor = 2.5
        elif self.credit_score >= 600:
            pre_approval_factor = 2.0
        elif self.credit_score >= 500:
            pre_approval_factor = 1.5
        else:
            pre_approval_factor = 1.0

        pre_approval_amount = self.income * pre_approval_factor * (1 - self.debt_to_income_ratio)
        return pre_approval_amount

