        else:
            print(f"Proposal {proposal_id} already exists.")

    def vote_on_proposal(self, proposal_id, voter_id, vote):
        if proposal_id in self.proposals and voter_id not in self.votes[proposal_id]:
            self.votes[proposal_id].append((voter_id, vote))
            print(f"Voter {voter_id} has voted {vote} on proposal {proposal_id}.")
        else:
            print("Invalid proposal ID or voter has already voted.")

    def execute_rule(self, proposal_id, quorum):
        if proposal_id in self.proposals:
            votes = self.votes[proposal_id]
            if len(votes) >= quorum:
                for voter_id, vote in votes:
                    if vote == "yes":
                        print(f"Rule '{self.proposals[proposal_id]}' executed by voter {voter_id}.")
                    else:
                        print(f"Rule '{self.proposals[proposal_id]}' rejected by voter {voter_id}.")
            else:
                print("Not enough votes to execute the rule.")
        else:
            print("Proposal ID not found.")

