import hashlib
import hmac
import os
from datetime import datetime, timedelta
from cryptography.fernet import Fernet

class BiometricLogin:
    def __init__(self):
        self.users = {}
        self.key = Fernet.generate_key()
        self.cipher_suite = Fernet(self.key)

    def enroll_biometric_data(self, username, biometric_data):
        if username in self.users:
            raise ValueError("User already enrolled")
        salt = os.urandom(16)
        biometric_hash = self._hash_biometric_data(biometric_data, salt)
        self.users[username] = {'salt': salt, 'biometric_hash': biometric_hash, 'session_token': None}

    def verify_biometric_data(self, username, biometric_data):
        if username not in self.users:
            raise ValueError("User not enrolled")
        user_data = self.users[username]
        biometric_hash = self._hash_biometric_data(biometric_data, user_data['salt'])
        if hmac.compare_digest(user_data['biometric_hash'], biometric_hash):
            user_data['session_token'] = self._generate_session_token()
            return True
        return False

    def manage_user_sessions(self, username):
        if username in self.users:
            user_data = self.users[username]
            if user_data['session_token']:
                expiration_time = datetime.utcnow() + timedelta(hours=1)
                if datetime.utcnow() > expiration_time:
                    user_data['session_token'] = None
                    return False
                return True
        return False

    def _hash_biometric_data(self, biometric_data, salt):
        return hashlib.pbkdf2_hmac('sha256', biometric_data.encode('utf-8'), salt, 100000)

    def _generate_session_token(self):
        return self.cipher_suite.encrypt(os.urandom(16))

