from datetime import datetime

class BankAccount:
    def __init__(self, account_number, account_type, balance=0):
        self.account_number = account_number
        self.account_type = account_type
        self.balance = balance
        self.transactions = []

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            self.transactions.append((datetime.now(), f"Deposited {amount}"))
            return True
        return False

    def withdraw(self, amount):
        if 0 < amount <= self.balance:
            self.balance -= amount
            self.transactions.append((datetime.now(), f"Withdrew {amount}"))
            return True
        return False

    def transfer(self, recipient, amount):
        if 0 < amount <= self.balance:
            self.balance -= amount
            recipient.deposit(amount)
            self.transactions.append((datetime.now(), f"Transferred {amount} to {recipient.account_number}"))
            recipient.transactions.append((datetime.now(), f"Received {amount} from {self.account_number}"))
            return True
        return False

    def get_balance(self):
        return self.balance

    def get_transactions(self):
        return self.transactions

