import hashlib
from datetime import datetime

class ESignatureManager:
    def __init__(self):
        self.documents = {}

    def add_document(self, doc_id, document_details):
        if doc_id in self.documents:
            raise ValueError("Document ID already exists")
        self.documents[doc_id] = {
            'details': document_details,
            'signatures': {},
            'timestamp': None
        }

    def update_document_details(self, doc_id, document_details):
        if doc_id not in self.documents:
            raise ValueError("Document ID does not exist")
        self.documents[doc_id]['details'] = document_details

    def add_signature(self, doc_id, user_id, signature):
        if doc_id not in self.documents:
            raise ValueError("Document ID does not exist")
        if user_id in self.documents[doc_id]['signatures']:
            raise ValueError("User has already signed the document")
        self.documents[doc_id]['signatures'][user_id] = signature
        self.documents[doc_id]['timestamp'] = datetime.now()

    def update_signature(self, doc_id, user_id, new_signature):
        if doc_id not in self.documents:
            raise ValueError("Document ID does not exist")
        if user_id not in self.documents[doc_id]['signatures']:
            raise ValueError("User has not signed the document")
        self.documents[doc_id]['signatures'][user_id] = new_signature

    def verify_signature(self, doc_id, user_id, signature):
        if doc_id not in self.documents:
            raise ValueError("Document ID does not exist")
        if user_id not in self.documents[doc_id]['signatures']:
            raise ValueError("User has not signed the document")
        stored_signature = self.documents[doc_id]['signatures'][user_id]
        return hashlib.sha256(stored_signature.encode()).hexdigest() == hashlib.sha256(signature.encode()).hexdigest()

# Example usage:
es_manager = ESignatureManager()
es_manager.add_document('doc1', 'Mortgage Agreement')
es_manager.add_signature('doc1', 'user1', 'user1_signature')
print(es_manager.verify_signature('doc1', 'user1', 'user1_signature'))  # True

import numpy as np
import pandas as pd

class LoanTermManager:
    def __init__(self, loan_data):
        self.loan_data = loan_data
        self._optimize_memory()

    def _optimize_memory(self):
        for col in self.loan_data.select_dtypes(include=[np.int64]).columns:
            self.loan_data[col] = self.loan_data[col].astype(np.int32)
        for col in self.loan_data.select_dtypes(include=[np.float64]).columns:
            self.loan_data[col] = self.loan_data[col].astype(np.float32)

    def add_loan(self, loan_id, term, interest_rate):
        new_loan = pd.DataFrame({'loan_id': [loan_id], 'term': [term], 'interest_rate': [interest_rate]})
        self._optimize_memory()
        return pd.concat([self.loan_data, new_loan], ignore_index=True)

    def get_loan_term(self, loan_id):
        return self.loan_data.loc[self.loan_data['loan_id'] == loan_id, 'term'].values[0]

    def get_loan_interest_rate(self, loan_id):
        return self.loan_data.loc[self.loan_data['loan_id'] == loan_id, 'interest_rate'].values[0]

    def update_loan_term(self, loan_id, new_term):
        self.loan_data.loc[self.loan_data['loan_id'] == loan_id, 'term'] = new_term
        self._optimize_memory()
        return self.loan_data

    def update_loan_interest_rate(self, loan_id, new_interest_rate):
        self.loan_data.loc[self.loan_data['loan_id'] == loan_id, 'interest_rate'] = new_interest_rate
        self._optimize_memory()
        return self.loan_data

    def delete_loan(self, loan_id):
        self.loan_data = self.loan_data[self.loan_data['loan_id'] != loan_id]
        self._optimize_memory()
        return self.loan_data

class CreditScorer:
    def __init__(self, payment_history, credit_utilization):
        self.payment_history = payment_history
        self.credit_utilization = credit_utilization

    def calculate_score(self):
        score = 0
        if self.payment_history == "Good":
            score += 20
        elif self.payment_history == "Fair":
            score += 10
        elif self.payment_history == "Poor":
            score -= 10

        if self.credit_utilization < 0.3:
            score += 15
        elif self.credit_utilization < 0.6:
            score += 5
        elif self.credit_utilization >= 0.6:
            score -= 10

        return score

import threading
from collections import defaultdict

class AccountManager:
    def __init__(self):
        self.account_locks = defaultdict(threading.Lock)
        self.account_statuses = defaultdict(bool)

    def lock_account(self, account_id):
        with self.account_locks[account_id]:
            if self.account_statuses[account_id]:
                raise ValueError(f"Account {account_id} is already locked.")
            self.account_statuses[account_id] = True

    def unlock_account(self, account_id):
        with self.account_locks[account_id]:
            if not self.account_statuses[account_id]:
                raise ValueError(f"Account {account_id} is not locked.")
            self.account_statuses[account_id] = False

