import heapq
from collections import defaultdict
import numpy as np

class RealTimePricingEngine:
    def __init__(self):
        self.prices = defaultdict(float)
        self.order_books = defaultdict(lambda: {'bids': [], 'asks': []})

    def update_price(self, asset, price):
        self.prices[asset] = price

    def calculate_volatility(self, asset, period=10):
        price_data = [self.prices[asset] for _ in range(period)]
        return np.std(price_data)

    def add_order(self, asset, side, price, quantity):
        if side == 'buy':
            heapq.heappush(self.order_books[asset]['bids'], (-price, quantity))
        elif side == 'sell':
            heapq.heappush(self.order_books[asset]['asks'], (price, quantity))

    def get_best_bid(self, asset):
        if self.order_books[asset]['bids']:
            return -self.order_books[asset]['bids'][0][0]
        return None

    def get_best_ask(self, asset):
        if self.order_books[asset]['asks']:
            return self.order_books[asset]['asks'][0][0]
        return None

    def execute_trade(self, asset, side, price, quantity):
        if side == 'buy':
            best_ask = self.get_best_ask(asset)
            if best_ask and best_ask <= price:
                if self.order_books[asset]['asks'][0][1] >= quantity:
                    self.order_books[asset]['asks'][0] = (self.order_books[asset]['asks'][0][0], self.order_books[asset]['asks'][0][1] - quantity)
                    return True
                else:
                    quantity -= self.order_books[asset]['asks'][0][1]
                    heapq.heappop(self.order_books[asset]['asks'])
                    return self.execute_trade(asset, side, price, quantity)
            return False
        elif side == 'sell':
            best_bid = self.get_best_bid(asset)
            if best_bid and best_bid >= price:
                if self.order_books[asset]['bids'][0][1] >= quantity:
                    self.order_books[asset]['bids'][0] = (self.order_books[asset]['bids'][0][0], self.order_books[asset]['bids'][0][1] - quantity)
                    return True
                else:
                    quantity -= self.order_books[asset]['bids'][0][1]
                    heapq.heappop(self.order_books[asset]['bids'])
                    return self.execute_trade(asset, side, price, quantity)
            return False

# Example usage
