from datetime import datetime
from typing import Dict, Any

class TradeRecord:
    def __init__(self, timestamp: datetime, counterparty: str, value: float):
        self.timestamp = self.validate_timestamp(timestamp)
        self.counterparty = self.validate_counterparty(counterparty)
        self.value = self.validate_value(value)

    @staticmethod
    def validate_timestamp(timestamp: datetime) -> datetime:
        if not isinstance(timestamp, datetime):
            raise ValueError("Timestamp must be a datetime object")
        if timestamp < datetime(2016, 1, 1):
            raise ValueError("Timestamp must be on or after January 1, 2016")
        return timestamp

    @staticmethod
    def validate_counterparty(counterparty: str) -> str:
        if not isinstance(counterparty, str) or len(counterparty.strip()) == 0:
            raise ValueError("Counterparty must be a non-empty string")
        return counterparty

    @staticmethod
    def validate_value(value: float) -> float:
        if not isinstance(value, (int, float)) or value <= 0:
            raise ValueError("Trade value must be a positive number")
        return value

    def to_dict(self) -> Dict[str, Any]:
        return {
            "timestamp": self.timestamp,
            "counterparty": self.counterparty,
            "value": self.value
        }

