import hashlib
import time
import threading
from queue import Queue

class BiometricLoginSystem:
    def __init__(self):
        self.users = {}
        self.biometric_data = {}
        self.lock = threading.Lock()
        self.auth_queue = Queue()

    def add_user(self, user_id, biometric_hash):
        with self.lock:
            self.users[user_id] = biometric_hash

    def add_biometric_data(self, user_id, biometric_data):
        with self.lock:
            self.biometric_data[user_id] = biometric_data

    def authenticate_user(self, user_id, biometric_data):
        if user_id not in self.users:
            return False, "User not found"

        biometric_hash = hashlib.sha256(biometric_data.encode()).hexdigest()
        if biometric_hash != self.users[user_id]:
            return False, "Authentication failed"

        return True, "Authentication successful"

    def start_authentication_thread(self):
        threading.Thread(target=self._authentication_worker, daemon=True).start()

    def _authentication_worker(self):
        while True:
            user_id, biometric_data = self.auth_queue.get()
            if user_id is None:
                break
            start_time = time.time()
            result, message = self.authenticate_user(user_id, biometric_data)
            end_time = time.time()
            latency = end_time - start_time
            print(f"User ID: {user_id}, Result: {result}, Message: {message}, Latency: {latency:.4f} seconds")
            self.auth_queue.task_done()

    def submit_authentication_request(self, user_id, biometric_data):
        self.auth_queue.put((user_id, biometric_data))

# Example usage
if __name__ == "__main__":
    bms = BiometricLoginSystem()
    bms.add_user("user1", hashlib.sha256("biometric_data_user1".encode()).hexdigest())
    bms.add_biometric_data("user1", "biometric_data_user1")
    bms.start_authentication_thread()

    bms.submit_authentication_request("user1", "biometric_data_user1")
    bms.submit_authentication_request("user1", "incorrect_biometric_data_user1")

import re

class LoanPreApprovalValidator:
    def __init__(self):
        pass

    def validate_social_security_number(self, ssn):
        pattern = re.compile(r'^\d{3}-\d{2}-\d{4}$')
        return bool(pattern.match(ssn))

    def validate_date(self, date_str):
        pattern = re.compile(r'^\d{2}/\d{2}/\d{4}$')
        if not pattern.match(date_str):
            return False
        month, day, year = map(int, date_str.split('/'))
        if month < 1 or month > 12:
            return False
        if day < 1 or day > 31:
            return False
        if year < 1900 or year > 2100:
            return False
        return True

    def validate_loan_amount(self, amount):
        pattern = re.compile(r'^\d+(\.\d{1,2})?$')
        return bool(pattern.match(amount))

