import datetime

class FraudDetectionSystem:
    def __init__(self):
        self.login_attempts = {}

    def record_login_attempt(self, user_id, location):
        if user_id not in self.login_attempts:
            self.login_attempts[user_id] = []
        self.login_attempts[user_id].append((datetime.datetime.now(), location))

    def is_suspicious(self, user_id, threshold=3):
        attempts = self.login_attempts.get(user_id, [])
        if len(attempts) < threshold:
            return False
        latest_attempt_time = attempts[-1][0]
        for attempt in attempts[:-1]:
            if (latest_attempt_time - attempt[0]).total_seconds() < 60:
                return True
        return False

