import re

class LoanCalculator:
    def __init__(self, loan_amount, interest_rate, loan_term):
        self.loan_amount = loan_amount
        self.interest_rate = interest_rate
        self.loan_term = loan_term

    def validate_input(self):
        if not isinstance(self.loan_amount, (int, float)) or self.loan_amount <= 0:
            raise ValueError("Loan amount must be a positive number.")
        if not re.match(r'^\d+\.\d{1,2}$', str(self.interest_rate)) or float(self.interest_rate) <= 0:
            raise ValueError("Interest rate must be a positive decimal number with up to two decimal places.")
        if not isinstance(self.loan_term, int) or self.loan_term <= 0:
            raise ValueError("Loan term must be a positive integer.")

    def calculate_monthly_repayment(self):
        self.validate_input()
        monthly_repayment = (self.loan_amount * self.interest_rate) / (1 - (1 + self.interest_rate) ** -self.loan_term)
        return monthly_repayment

