class Merchant:
    def __init__(self, merchant_id, merchant_name):
        self.merchant_id = merchant_id
        self.merchant_name = merchant_name
        self.transactions = []

    def process_transaction(self, amount, customer_id):
        transaction = {'amount': amount, 'customer_id': customer_id}
        self.transactions.append(transaction)
        return transaction

    def manage_customer_payment(self, customer_id, amount):
        for transaction in self.transactions:
            if transaction['customer_id'] == customer_id and transaction['amount'] == amount:
                return True
        return False

    def handle_refund(self, transaction_id, amount):
        for i, transaction in enumerate(self.transactions):
            if transaction['id'] == transaction_id:
                self.transactions[i]['amount'] -= amount
                return True
        return False

    def calculate_total_revenue(self):
        total_revenue = sum(transaction['amount'] for transaction in self.transactions)
        return total_revenue

