from abc import ABC, abstractmethod
from typing import Dict, Any

class DocumentMeta(type):
    _registry: Dict[str, 'Document'] = {}

    def __new__(cls, name, bases, dct):
        new_cls = super().__new__(cls, name, bases, dct)
        cls._registry[name] = new_cls
        return new_cls

    @classmethod
    def get_document(cls, document_type: str):
        return cls._registry.get(document_type, None)

class Document(ABC, metaclass=DocumentMeta):
    @abstractmethod
    def validate(self, data: Dict[str, Any]) -> bool:
        pass

class MortgageApplication(Document):
    def validate(self, data: Dict[str, Any]) -> bool:
        required_fields = ['name', 'address', 'income', 'loan_amount']
        return all(field in data for field in required_fields)

class LoanAgreement(Document):
    def validate(self, data: Dict[str, Any]) -> bool:
        required_fields = ['lender', 'borrower', 'loan_amount', 'interest_rate']
        return all(field in data for field in required_fields)

class DocumentUploader:
    def __init__(self):
        self.documents = {}

    def upload_document(self, document_type: str, data: Dict[str, Any]):
        document_class = DocumentMeta.get_document(document_type)
        if document_class:
            if document_class.validate(data):
                self.documents[document_type] = data
                print(f"Document of type {document_type} uploaded successfully.")
            else:
                print(f"Validation failed for document of type {document_type}.")
        else:
            print(f"Document type {document_type} not supported.")

