import hashlib
import time
from typing import Dict, Optional

class AMLKYCRecord:
    def __init__(self, customer_id: str, name: str, address: str, email: str):
        self.customer_id = customer_id
        self.name = name
        self.address = address
        self.email = email
        self.status = "Pending"
        self.last_updated = time.time()
        self.hash = self._generate_hash()

    def _generate_hash(self) -> str:
        data = f"{self.customer_id}{self.name}{self.address}{self.email}{self.status}{self.last_updated}"
        return hashlib.sha256(data.encode()).hexdigest()

    def update_status(self, new_status: str):
        if new_status in ["Pending", "Approved", "Rejected"]:
            self.status = new_status
            self.last_updated = time.time()
            self.hash = self._generate_hash()
        else:
            raise ValueError("Invalid status update")

    def to_dict(self) -> Dict:
        return {
            "customer_id": self.customer_id,
            "name": self.name,
            "address": self.address,
            "email": self.email,
            "status": self.status,
            "last_updated": self.last_updated,
            "hash": self.hash
        }

class AMLKYCManager:
    def __init__(self):
        self.records: Dict[str, AMLKYCRecord] = {}

    def add_record(self, record: AMLKYCRecord):
        if record.customer_id in self.records:
            raise ValueError("Customer ID already exists")
        self.records[record.customer_id] = record

    def update_record(self, customer_id: str, new_status: str):
        if customer_id not in self.records:
            raise ValueError("Customer ID not found")
        self.records[customer_id].update_status(new_status)

    def get_record(self, customer_id: str) -> Optional[Dict]:
        if customer_id not in self.records:
            return None
        return self.records[customer_id].to_dict()

    def remove_record(self, customer_id: str):
        if customer_id not in self.records:
            raise ValueError("Customer ID not found")
        del self.records[customer_id]

def check_gdpr_compliance(user_info):
    """
    This function checks if the user's personal information meets the GDPR data minimization principle.

    Parameters:
    user_info (dict): A dictionary containing the user's personal information.

    Returns:
    bool: True if the data collection is compliant, False otherwise.
    """
    required_info = {'name': str, 'email': str, 'age': int}

    for key, value_type in required_info.items():
        if key not in user_info or not isinstance(user_info[key], value_type):
            return False

    return True

import hashlib
from datetime import datetime

class Blockchain:
    def __init__(self):
        self.chain = []
        self.create_block(proof=1, previous_hash='0')

    def create_block(self, proof, previous_hash):
        block = {
            'index': len(self.chain) + 1,
            'timestamp': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            'proof': proof,
            'previous_hash': previous_hash
        }
        self.chain.append(block)
        return block

    def get_previous_block(self):
        return self.chain[-1]

    def proof_of_work(self, previous_proof):
        new_proof = 1
        check_proof = False
        while check_proof is False:
            hash_operation = hashlib.sha256(str(new_proof**2 - previous_proof**2).encode()).hexdigest()
            if hash_operation[:4] == '0000':
                check_proof = True
            else:
                new_proof += 1
        return new_proof

    def hash_block(self, block):
        encoded_block = str(block).encode()
        return hashlib.sha256(encoded_block).hexdigest()

    def is_chain_valid(self, chain):
        previous_block = chain[0]
        block_index = 1
        while block_index < len(chain):
            block = chain[block_index]
            if block['previous_hash'] != self.hash_block(previous_block):
                return False
            previous_proof = previous_block['proof']
            proof = block['proof']
            hash_operation = hashlib.sha256(str(proof**2 - previous_proof**2).encode()).hexdigest()
            if hash_operation[:4] != '0000':
                return False
            previous_block = block
            block_index += 1
        return True

