from abc import ABC, abstractmethod

class FungibleTokenMeta(type):
    def __new__(cls, name, bases, dct):
        # Enforce abstract base class
        if not issubclass(dct, ABC):
            raise TypeError("FungibleToken classes must inherit from ABC")

        # Enforce abstract method
        if not all(issubclass(dct[method], abstractmethod) for method in ['transfer', 'balance_of']):
            raise TypeError("FungibleToken classes must implement 'transfer' and 'balance_of' methods")

        # Enforce specific data types for attributes
        for attr, value in dct.items():
            if attr.startswith('_'):
                continue
            if not isinstance(value, (int, str)):
                raise TypeError(f"Attribute '{attr}' must be of type int or str")

        return super().__new__(cls, name, bases, dct)

class FungibleToken(metaclass=FungibleTokenMeta):
    def __init__(self, owner, balance):
        self._owner = owner
        self._balance = balance

    @abstractmethod
    def transfer(self, recipient, amount):
        pass

    @abstractmethod
    def balance_of(self):
        return self._balance

class ERC20Token(FungibleToken):
    def transfer(self, recipient, amount):
        if amount > self._balance:
            raise ValueError("Insufficient balance")
        self._balance -= amount
        recipient._balance += amount

    def balance_of(self):
        return self._balance

import threading
import queue
import time

# Define a class for transaction processing
class TransactionProcessor:
    def __init__(self, num_workers):
        self.queue = queue.Queue()
        self.workers = []
        for _ in range(num_workers):
            worker = threading.Thread(target=self.process_transaction)
            worker.start()
            self.workers.append(worker)

    def process_transaction(self):
        while True:
            transaction = self.queue.get()
            if transaction is None:
                break
            self.handle_transaction(transaction)
            self.queue.task_done()

    def handle_transaction(self, transaction):
        # Simulate transaction processing
        time.sleep(1)
        print(f"Processed transaction: {transaction}")

    def add_transaction(self, transaction):
        self.queue.put(transaction)

    def stop(self):
        for _ in self.workers:
            self.queue.put(None)
        for worker in self.workers:
            worker.join()

