import heapq

class Transaction:
    def __init__(self, transaction_id, amount, urgency):
        self.transaction_id = transaction_id
        self.amount = amount
        self.urgency = urgency

    def __lt__(self, other):
        return self.urgency < other.urgency

class MobileWallet:
    def __init__(self):
        self.transactions = []
        self.transaction_dict = {}

    def add_transaction(self, transaction_id, amount, urgency):
        if transaction_id in self.transaction_dict:
            raise ValueError("Transaction ID already exists")

        transaction = Transaction(transaction_id, amount, urgency)
        heapq.heappush(self.transactions, transaction)
        self.transaction_dict[transaction_id] = transaction

    def update_transaction(self, transaction_id, amount, urgency):
        if transaction_id not in self.transaction_dict:
            raise ValueError("Transaction ID does not exist")

        transaction = self.transaction_dict[transaction_id]
        transaction.amount = amount
        transaction.urgency = urgency
        heapq.heapify(self.transactions)

    def get_transaction(self, transaction_id):
        if transaction_id not in self.transaction_dict:
            raise ValueError("Transaction ID does not exist")

        return self.transaction_dict[transaction_id]

    def get_next_transaction(self):
        if not self.transactions:
            raise ValueError("No transactions available")

        return heapq.heappop(self.transactions)

# Example usage
wallet = MobileWallet()
wallet.add_transaction(1, 100, 2)
wallet.add_transaction(2, 50, 1)
wallet.add_transaction(3, 200, 3)

print(wallet.get_next_transaction())  # Output: Transaction(transaction_id=2, amount=50, urgency=1)
print(wallet.get_next_transaction())  # Output: Transaction(transaction_id=1, amount=100, urgency=2)
print(wallet.get_next_transaction())  # Output: Transaction(transaction_id=3, amount=200, urgency=3)

import requests

class PaymentAPIManager:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = "https://api.paymentprovider.com/v1"

    def make_request(self, endpoint, method='GET', data=None):
        headers = {
            'Authorization': f'Bearer {self.api_key}',
            'Content-Type': 'application/json'
        }
        url = f"{self.base_url}{endpoint}"

        if method == 'GET':
            response = requests.get(url, headers=headers)
        elif method == 'POST':
            response = requests.post(url, headers=headers, json=data)
        else:
            raise ValueError("Unsupported HTTP method")

        if response.status_code == 200:
            return True, response.json()
        else:
            return False, response.json()

class RefinanceCalculator:
    def __init__(self, current_rate, current_balance, new_rate):
        self.current_rate = current_rate
        self.current_balance = current_balance
        self.new_rate = new_rate

    def calculate_monthly_payment(self, rate, balance, years):
        return (rate * balance) / (1 - (1 + rate) ** (-years * 12))

    def calculate_savings(self, years):
        current_payment = self.calculate_monthly_payment(self.current_rate, self.current_balance, years)
        new_payment = self.calculate_monthly_payment(self.new_rate, self.current_balance, years)
        return (current_payment - new_payment) * years * 12

    def generate_summary_report(self):
        savings = self.calculate_savings(30)  # Assuming a 30-year mortgage
        return f"Potential savings over 30 years: ${savings:.2f}"

