import hashlib
from datetime import datetime

class BlockchainTransaction:
    def __init__(self, transaction_id, sender_address, receiver_address, transaction_amount):
        self.transaction_id = transaction_id
        self.sender_address = sender_address
        self.receiver_address = receiver_address
        self.transaction_amount = transaction_amount
        self.timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        self.transaction_hash = self.calculate_hash()

    def calculate_hash(self):
        transaction_string = f"{self.transaction_id}{self.sender_address}{self.receiver_address}{self.transaction_amount}{self.timestamp}"
        return hashlib.sha256(transaction_string.encode()).hexdigest()

    def validate_transaction(self):
        # Simple validation: check if all fields are non-empty
        if not self.transaction_id or not self.sender_address or not self.receiver_address or self.transaction_amount <= 0:
            return False
        return True

    def serialize(self):
        return {
            "transaction_id": self.transaction_id,
            "sender_address": self.sender_address,
            "receiver_address": self.receiver_address,
            "transaction_amount": self.transaction_amount,
            "timestamp": self.timestamp,
            "transaction_hash": self.transaction_hash
        }

