import weakref
from collections import defaultdict

class PolicyDocument:
    def __init__(self, policy_id, details):
        self.policy_id = policy_id
        self.details = details

class PolicyDocumentPool:
    _pool = weakref.WeakValueDictionary()

    @classmethod
    def get_instance(cls, policy_id, details=None):
        if policy_id not in cls._pool:
            if details is None:
                raise ValueError("Details are required for new policy documents")
            cls._pool[policy_id] = PolicyDocument(policy_id, details)
        return cls._pool[policy_id]

    @classmethod
    def get_all(cls):
        return list(cls._pool.values())

class LazyPolicyDocumentLoader:
    def __init__(self, policy_ids):
        self.policy_ids = policy_ids
        self._loaded_policies = defaultdict(lambda: None)

    def load_policy(self, policy_id):
        if self._loaded_policies[policy_id] is None:
            self._loaded_policies[policy_id] = PolicyDocumentPool.get_instance(policy_id)
        return self._loaded_policies[policy_id]

    def load_all_policies(self):
        for policy_id in self.policy_ids:
            self.load_policy(policy_id)
        return self._loaded_policies.values()

import threading
import queue
import hashlib
import time

class SecureTransactionProcessor:
    def __init__(self, num_workers=10):
        self.transaction_queue = queue.Queue()
        self.workers = []
        self.lock = threading.Lock()
        self.stop_event = threading.Event()

        for _ in range(num_workers):
            worker = threading.Thread(target=self.worker)
            worker.start()
            self.workers.append(worker)

    def worker(self):
        while not self.stop_event.is_set():
            try:
                transaction = self.transaction_queue.get(timeout=1)
                if transaction is None:
                    continue
                self.process_transaction(transaction)
                self.transaction_queue.task_done()
            except queue.Empty:
                continue

    def process_transaction(self, transaction):
        # Simulate transaction processing
        time.sleep(0.1)
        # Hash the transaction for security
        transaction_hash = hashlib.sha256(str(transaction).encode()).hexdigest()
        print(f"Processed transaction: {transaction} with hash: {transaction_hash}")

    def submit_transaction(self, transaction):
        with self.lock:
            self.transaction_queue.put(transaction)

    def stop(self):
        for _ in range(len(self.workers)):
            self.transaction_queue.put(None)
        for worker in self.workers:
            worker.join()

# Example usage
if __name__ == "__main__":
    processor = SecureTransactionProcessor(num_workers=5)
    for i in range(20):
        processor.submit_transaction(f"Transaction {i}")
    processor.stop()

