from contextlib import contextmanager
from typing import Callable, Any

class ZKPContextManager:
    def __init__(self, proof_generator: Callable[[], Any], proof_verifier: Callable[[Any], bool]):
        self.proof_generator = proof_generator
        self.proof_verifier = proof_verifier
        self.proof = None

    def __enter__(self):
        self.proof = self.proof_generator()
        return self.proof

    def __exit__(self, exc_type, exc_value, traceback):
        if exc_type is None:
            return self.proof_verifier(self.proof)
        return False

@contextmanager
def zkp_context(proof_generator: Callable[[], Any], proof_verifier: Callable[[Any], bool]):
    manager = ZKPContextManager(proof_generator, proof_verifier)
    try:
        yield manager.__enter__()
    except Exception as e:
        raise e
    finally:
        manager.__exit__(None, None, None)

class Portfolio:
    def __init__(self):
        self.assets = {}

    def add_asset(self, asset, quantity, price):
        if asset in self.assets:
            self.assets[asset] += quantity * price
        else:
            self.assets[asset] = quantity * price

    def remove_asset(self, asset, quantity, price):
        if asset in self.assets:
            if self.assets[asset] >= quantity * price:
                self.assets[asset] -= quantity * price
                if self.assets[asset] == 0:
                    del self.assets[asset]
            else:
                raise ValueError("Insufficient quantity to remove")
        else:
            raise KeyError("Asset not found in portfolio")

    def calculate_total_value(self, prices):
        total_value = 0
        for asset, quantity in self.assets.items():
            if asset in prices:
                total_value += quantity * prices[asset]
            else:
                raise KeyError(f"Price for {asset} not found")
        return total_value

