from typing import Dict, List

class NFT:
    def __init__(self, token_id: int, owner: str, metadata: Dict):
        self.token_id = token_id
        self.owner = owner
        self.metadata = metadata

class NFTManager:
    def __init__(self):
        self.nfts: Dict[int, NFT] = {}

    def add_nft(self, token_id: int, owner: str, metadata: Dict):
        if token_id in self.nfts:
            raise ValueError(f"NFT with token_id {token_id} already exists")
        self.nfts[token_id] = NFT(token_id, owner, metadata)

    def get_nft(self, token_id: int) -> NFT:
        if token_id not in self.nfts:
            raise ValueError(f"NFT with token_id {token_id} does not exist")
        return self.nfts[token_id]

    def transfer_nft(self, token_id: int, new_owner: str):
        if token_id not in self.nfts:
            raise ValueError(f"NFT with token_id {token_id} does not exist")
        self.nfts[token_id].owner = new_owner

    def get_all_nfts(self) -> List[NFT]:
        return list(self.nfts.values())

