class PolicyManager:
    def __init__(self):
        self.policies = pd.DataFrame(columns=['policy_id', 'customer_name', 'policy_details'])

    def add_policy(self, policy_id, customer_name, policy_details):
        new_policy = pd.DataFrame({
            'policy_id': [policy_id],
            'customer_name': [customer_name],
            'policy_details': [json.dumps(policy_details)]
        })
        self.policies = pd.concat([self.policies, new_policy], ignore_index=True)

    def update_policy(self, policy_id, policy_details):
        self.policies.loc[self.policies['policy_id'] == policy_id, 'policy_details'] = json.dumps(policy_details)

    def delete_policy(self, policy_id):
        self.policies = self.policies[self.policies['policy_id'] != policy_id]

    def search_policy(self, policy_id=None, customer_name=None):
        if policy_id:
            return self.policies[self.policies['policy_id'] == policy_id]
        elif customer_name:
            return self.policies[self.policies['customer_name'] == customer_name]
        else:
            return self.policies

class TaxWorkflowMeta(type):
    states = []

    def __new__(cls, name, bases, attrs):
        new_class = super().__new__(cls, name, bases, attrs)
        cls.states.append(new_class)
        return new_class

    @classmethod
    def get_states(cls):
        return cls.states

class TaxWorkflow(metaclass=TaxWorkflowMeta):
    def __init__(self, state):
        self.state = state

    def transition_to(self, new_state):
        if new_state in self.state.allowed_transitions:
            self.state = new_state
        else:
            raise ValueError("Invalid transition")

class State:
