from abc import ABC, abstractmethod
from typing import Any, Dict

class DeviceFingerprint(ABC):
    @abstractmethod
    def get_attributes(self) -> Dict[str, Any]:
        pass

class DeviceFingerprintRegistry(type):
    _registry: Dict[str, 'DeviceFingerprint'] = {}

    def __new__(cls, name, bases, dct):
        if name != 'DeviceFingerprint':
            attributes = dct['get_attributes']()
            if any(cls._registry.get(attr, None) is not None for attr in attributes.values()):
                raise ValueError(f"Device with attributes {attributes} already exists.")
            cls._registry[tuple(sorted(attributes.values()))] = dct
        return super().__new__(cls, name, bases, dct)

class UniqueDeviceFingerprint(DeviceFingerprint, metaclass=DeviceFingerprintRegistry):
    def __init__(self, device_id: str, ip_address: str, user_agent: str):
        self.device_id = device_id
        self.ip_address = ip_address
        self.user_agent = user_agent

    def get_attributes(self) -> Dict[str, Any]:
        return {
            'device_id': self.device_id,
            'ip_address': self.ip_address,
            'user_agent': self.user_agent
        }

