        validate = lambda x, y: isinstance(x, (int, float)) and isinstance(y, (int, float)) and x > 0 and y > 0
        return validate(self.current_rate, self.new_rate) and validate(self.loan_amount, self.loan_term)

    def calculate_savings(self):
        if not self.validate_input():
            return "Invalid input"

        current_interest = self.loan_amount * self.current_rate * self.loan_term
        new_interest = self.loan_amount * self.new_rate * self.loan_term
        savings = current_interest - new_interest
        return savings

    def is_eligible(self, credit_score, income):
        min_credit_score = 650
        min_income = 50000
        is_eligible = lambda x, y: x >= min_credit_score and y >= min_income
        return is_eligible(credit_score, income)

