import re

class RegulatoryComplianceMeta(type):
    def __new__(cls, name, bases, dct):
        # Check attribute names
        for attr_name in dct:
            if not re.match(r'^[A-Za-z0-9_]+$', attr_name):
                raise ValueError(f"Attribute name '{attr_name}' is not compliant with regulatory standards.")

        # Check method names
        for method_name in dct:
            if not re.match(r'^[A-Za-z0-9_]+$', method_name):
                raise ValueError(f"Method name '{method_name}' is not compliant with regulatory standards.")

        # Check attribute types
        for attr_name, attr_value in dct.items():
            if isinstance(attr_value, property):
                getter = attr_value.fget
                setter = attr_value.fset
                if not callable(getter) or not callable(setter):
                    raise ValueError(f"Property '{attr_name}' must have callable getter and setter.")

        return super().__new__(cls, name, bases, dct)

class FinancialDataModel(metaclass=RegulatoryComplianceMeta):
