# Define the function to calculate the risk score
def calculate_risk_score(age, driving_history, vehicle_type):
    # Initialize the risk score
    risk_score = 0

    # Calculate risk based on age
    if age < 18:
        risk_score += 5
    elif age < 30:
        risk_score += 2
    elif age < 60:
        risk_score += 1
    else:
        risk_score += 3

    # Calculate risk based on driving history
    if driving_history == 'excellent':
        risk_score -= 2
    elif driving_history == 'good':
        risk_score -= 1
    elif driving_history == 'average':
        pass
    elif driving_history == 'poor':
        risk_score += 1
    else:
        risk_score += 2

    # Calculate risk based on vehicle type
    if vehicle_type == 'luxury':
        risk_score += 3
    elif vehicle_type == 'sports':
        risk_score += 2
    elif vehicle_type == 'compact':
        risk_score += 1
    else:
        risk_score += 2

    # Ensure the risk score is not negative
    if risk_score < 0:
        risk_score = 0

    return risk_score

