class FraudDetectionSystem:
    def __init__(self):
        self.claims = []

    def input_claim(self, policy_number, claim_amount, claim_date):
        self.claims.append({
            'policy_number': policy_number,
            'claim_amount': claim_amount,
            'claim_date': claim_date
        })

    def process_claims(self):
        suspicious_claims = []
        for i in range(len(self.claims)):
            claim = self.claims[i]
            if claim['claim_amount'] > 10000:
                suspicious_claims.append(claim)
            for j in range(i + 1, len(self.claims)):
                if self.claims[j]['policy_number'] == claim['policy_number']:
                    if abs((self.claims[j]['claim_date'] - claim['claim_date']).days) < 30:
                        suspicious_claims.append(claim)
                        suspicious_claims.append(self.claims[j])
        return suspicious_claims

    def output_result(self):
        suspicious_claims = self.process_claims()
        if suspicious_claims:
            print("Suspicious claims detected:")
            for claim in suspicious_claims:
                print(f"Policy Number: {claim['policy_number']}, Claim Amount: {claim['claim_amount']}, Claim Date: {claim['claim_date']}")
        else:
            print("No suspicious claims detected.")

