class SmartContractInteraction:
    def __init__(self):
        self.interactions = {}

    def add_interaction(self, contract_address, event_type, data):
        if contract_address not in self.interactions:
            self.interactions[contract_address] = {}
        if event_type not in self.interactions[contract_address]:
            self.interactions[contract_address][event_type] = []
        self.interactions[contract_address][event_type].append(data)

    def remove_interaction(self, contract_address, event_type, data):
        if contract_address in self.interactions and event_type in self.interactions[contract_address]:
            self.interactions[contract_address][event_type].remove(data)
            if not self.interactions[contract_address][event_type]:
                del self.interactions[contract_address][event_type]
            if not self.interactions[contract_address]:
                del self.interactions[contract_address]

    def query_interactions(self, contract_address=None, event_type=None):
        if contract_address and event_type:
            return self.interactions.get(contract_address, {}).get(event_type, [])
        elif contract_address:
            return self.interactions.get(contract_address, {})
        elif event_type:
            return {contract: self.interactions[contract].get(event_type, []) for contract in self.interactions}
        else:
            return self.interactions

