import threading

class CryptoPortfolio:
    def __init__(self):
        self.portfolio = {}
        self.lock = threading.Lock()

    def add_asset(self, asset, quantity):
        with self.lock:
            if asset in self.portfolio:
                self.portfolio[asset] += quantity
            else:
                self.portfolio[asset] = quantity

    def remove_asset(self, asset, quantity):
        with self.lock:
            if asset in self.portfolio and self.portfolio[asset] >= quantity:
                self.portfolio[asset] -= quantity
                if self.portfolio[asset] == 0:
                    del self.portfolio[asset]
            else:
                raise ValueError("Insufficient quantity or asset not found")

    def update_asset(self, asset, quantity):
        with self.lock:
            if asset in self.portfolio:
                self.portfolio[asset] = quantity
            else:
                raise ValueError("Asset not found")

    def get_portfolio_value(self, asset_prices):
        with self.lock:
            total_value = 0
            for asset, quantity in self.portfolio.items():
                if asset in asset_prices:
                    total_value += asset_prices[asset] * quantity
                else:
                    raise ValueError(f"Asset price for {asset} not available")
            return total_value

    def get_asset_quantity(self, asset):
        with self.lock:
            return self.portfolio.get(asset, 0)

    def get_all_assets(self):
        with self.lock:
            return self.portfolio.copy()

