class BlockchainPayment:
    def __init__(self):
        self.transactions = []

    def validate_transaction(self, transaction):
        # Basic validation (e.g., check if transaction is signed)
        return web3.eth.getTransaction(transaction['hash']) is not None

    def broadcast_transaction(self, transaction):
        # Broadcast transaction to the Blockchain network
        tx_hash = web3.eth.sendRawTransaction(json.dumps(transaction).encode('utf-8'))
        return tx_hash.hex()

    def update_transaction_history(self, transaction):
        # Update local transaction history
        self.transactions.append(transaction)

