import threading
import queue
import time

class GasManager:
    def __init__(self, gas_price, gas_limit):
        self.gas_price = gas_price
        self.gas_limit = gas_limit
        self.transaction_queue = queue.Queue()
        self.lock = threading.Lock()
        self.threads = []

    def calculate_gas_fee(self, gas_used):
        return gas_used * self.gas_price

    def manage_gas_limits(self, gas_limit):
        with self.lock:
            self.gas_limit = gas_limit

    def optimize_transaction_batches(self):
        while not self.transaction_queue.empty():
            batch = []
            while not self.transaction_queue.empty() and len(batch) < self.gas_limit:
                batch.append(self.transaction_queue.get())
            self.process_batch(batch)

    def process_batch(self, batch):
        # Simulate processing batch
        print(f"Processing batch of {len(batch)} transactions")
        time.sleep(1)

    def add_transaction(self, transaction):
        self.transaction_queue.put(transaction)
        if len(self.threads) < 4:
            thread = threading.Thread(target=self.optimize_transaction_batches)
            thread.start()
            self.threads.append(thread)

    def stop(self):
        for thread in self.threads:
            thread.join()

# Example usage
