import hashlib
from typing import Dict, Any

class SmartContractState:
    def __init__(self, initial_state: Dict[str, Any]):
        self.state = initial_state
        self.history = [initial_state.copy()]

    def transition(self, transition_function: callable):
        new_state = transition_function(self.state)
        self.state = new_state
        self.history.append(new_state)

    def verify(self, verification_function: callable):
        return verification_function(self.state, self.history)

    def hash_state(self):
        state_str = str(self.state)
        return hashlib.sha256(state_str.encode()).hexdigest()

    def get_state(self):
        return self.state

    def get_history(self):
        return self.history

