# Models
class Transaction(models.Model):
    transaction_id = models.CharField(max_length=100, unique=True)
    amount = models.DecimalField(max_digits=10, decimal_places=2)
    date = models.DateTimeField(auto_now_add=True)
    regulatory_status = models.CharField(max_length=50)

class RegulatoryRule(models.Model):
    rule_id = models.CharField(max_length=100, unique=True)
    description = models.TextField()
    threshold = models.DecimalField(max_digits=10, decimal_places=2)

class ComplianceLog(models.Model):
    log_id = models.AutoField(primary_key=True)
    transaction = models.ForeignKey(Transaction, on_delete=models.CASCADE)
    rule = models.ForeignKey(RegulatoryRule, on_delete=models.CASCADE)
    status = models.CharField(max_length=50)
    timestamp = models.DateTimeField(auto_now_add=True)

# Forms
class TransactionForm(forms.ModelForm):
    class Meta:
        model = Transaction
        fields = ['transaction_id', 'amount', 'date']

# Views
class TransactionView(View):
    def post(self, request):
        form = TransactionForm(request.POST)
        if form.is_valid():
            transaction = form.save(commit=False)
            # Validate transaction against regulatory rules
            for rule in RegulatoryRule.objects.all():
                if transaction.amount > rule.threshold:
                    log = ComplianceLog(transaction=transaction, rule=rule, status='Non-Compliant')
                    log.save()
                    transaction.regulatory_status = 'Non-Compliant'
                else:
                    log = ComplianceLog(transaction=transaction, rule=rule, status='Compliant')
                    log.save()
                    transaction.regulatory_status = 'Compliant'
            transaction.save()
            return HttpResponse('Transaction validated and logged successfully')
        else:
            return HttpResponse('Invalid transaction data', status=400)

