import threading
import queue
import time

class LoanApplicationProcessor:
    def __init__(self, num_workers):
        self.queue = queue.Queue()
        self.workers = []
        for _ in range(num_workers):
            worker = threading.Thread(target=self.process_application)
            worker.start()
            self.workers.append(worker)

    def process_application(self):
        while True:
            application = self.queue.get()
            if application is None:
                break
            self.handle_application(application)
            self.queue.task_done()

    def handle_application(self, application):
        # Simulate application processing
        time.sleep(1)
        print(f"Processed application: {application}")

    def submit_application(self, application):
        self.queue.put(application)

    def stop(self):
        for _ in self.workers:
            self.queue.put(None)
        for worker in self.workers:
            worker.join()

# Example usage
if __name__ == "__main__":
    processor = LoanApplicationProcessor(num_workers=5)
    applications = [f"App-{i}" for i in range(20)]
    for app in applications:
        processor.submit_application(app)
    processor.stop()

