import numpy as np
from typing import List

class ZeroKnowledgeProofManager:
    def __init__(self, max_proofs: int):
        self.max_proofs = max_proofs
        self.proofs = np.empty(max_proofs, dtype=object)
        self.proof_count = 0

    def add_proof(self, proof: object):
        if self.proof_count >= self.max_proofs:
            raise MemoryError("Maximum number of proofs reached")
        self.proofs[self.proof_count] = proof
        self.proof_count += 1

    def get_proofs(self) -> List[object]:
        return self.proofs[:self.proof_count].tolist()

    def clear_proofs(self):
        self.proofs[:self.proof_count] = [None] * self.proof_count
        self.proof_count = 0

