import re

class PaymentTransaction:
    def __init__(self, transaction_id, amount, payment_method, currency):
        self.transaction_id = transaction_id
        self.amount = amount
        self.payment_method = payment_method
        self.currency = currency

    def validate_amount(self):
        if not isinstance(self.amount, (int, float)) or self.amount <= 0:
            raise ValueError("Transaction amount must be a positive number")

    def validate_payment_method(self):
        valid_methods = ['credit_card', 'debit_card', 'paypal', 'bank_transfer']
        if self.payment_method not in valid_methods:
            raise ValueError(f"Invalid payment method. Must be one of: {', '.join(valid_methods)}")

    def validate_currency(self):
        if not re.match(r'^[A-Z]{3}$', self.currency):
            raise ValueError("Currency code must be a 3-letter ISO 4217 code")

    def validate(self):
        self.validate_amount()
        self.validate_payment_method()
        self.validate_currency()

