        return list(self.transactions.values())

import requests
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad, unpad

class CrossBorderPayment:
    def __init__(self, api_key, api_secret):
        self.api_key = api_key
        self.api_secret = api_secret
        self.base_url = "https://api.crossborderpayments.com"

    def encrypt_data(self, data):
        key = get_random_bytes(16)
        cipher = AES.new(key, AES.MODE_CBC)
        ct_bytes = cipher.encrypt(pad(data.encode('utf-8'), AES.block_size))
        iv = cipher.iv
        ct = iv + ct_bytes
        return ct, key

    def decrypt_data(self, ct, key):
        iv = ct[:16]
        ct = ct[16:]
        cipher = AES.new(key, AES.MODE_CBC, iv)
        pt = unpad(cipher.decrypt(ct), AES.block_size)
        return pt.decode('utf-8')

    def send_transaction(self, recipient, amount, currency):
        ct, key = self.encrypt_data(f"{recipient},{amount},{currency}")
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }
        data = {
            "encrypted_data": ct.hex(),
            "key": key.hex()
        }
        response = requests.post(f"{self.base_url}/transactions", headers=headers, json=data)
        if response.status_code == 200:
            return response.json()
        else:
            return None

import re

class LoanApprovalChecker:
    def check_status(self, notes):
        # Define patterns for different statuses
        patterns = {
            'approved': re.compile(r'\b(approved|approved)\b', re.IGNORECASE),
            'denied': re.compile(r'\b(denied|rejected)\b', re.IGNORECASE),
            'pending': re.compile(r'\b(pending|waiting)\b', re.IGNORECASE),
            'under review': re.compile(r'\b(under review|in review)\b', re.IGNORECASE)
        }

        # Check each pattern and return the first match found
        for status, pattern in patterns.items():
            if pattern.search(notes):
                return status

        # Return None if no status is found
        return None

