import pandas as pd

class BillPaymentHandler:
    def __init__(self, transactions_df):
        self.transactions_df = transactions_df.copy()
        self.accounts_df = self.initialize_accounts()

    def initialize_accounts(self):
        # Assuming the transactions_df has columns 'user_id' and 'balance'
        accounts_df = self.transactions_df[['user_id', 'balance']].drop_duplicates()
        accounts_df.set_index('user_id', inplace=True)
        return accounts_df

    def validate_transaction(self, transaction):
        # Check if the transaction amount is positive
        if transaction['amount'] <= 0:
            return False
        # Check if the user has sufficient balance
        if self.accounts_df.loc[transaction['user_id'], 'balance'] < transaction['amount']:
            return False
        return True

    def update_user_balance(self, transaction):
        if self.validate_transaction(transaction):
            self.accounts_df.loc[transaction['user_id'], 'balance'] -= transaction['amount']
            return True
        return False

    def log_payment_activity(self, transaction):
        log_entry = pd.DataFrame([transaction], columns=['user_id', 'amount', 'timestamp'])
        self.transactions_df = pd.concat([self.transactions_df, log_entry], ignore_index=True)

    def process_transaction(self, transaction):
        if self.update_user_balance(transaction):
            self.log_payment_activity(transaction)
            return True
        return False

