import re

class OrderManager:
    def __init__(self):
        self.orders = {}

    def parse_order_id(self, log_entry):
        # Regular expression to match order IDs in the log entry
        order_id_pattern = r'OrderID:(\d+)'
        match = re.search(order_id_pattern, log_entry)
        if match:
            return match.group(1)
        return None

    def log_order_entry(self, log_entry):
        order_id = self.parse_order_id(log_entry)
        if order_id:
            if order_id in self.orders:
                self.orders[order_id]['entries'] += 1
            else:
                self.orders[order_id] = {'entries': 1, 'exits': 0}
            print(f"Order {order_id} entry logged.")
        else:
            print("Invalid log entry.")

    def log_order_exit(self, log_entry):
        order_id = self.parse_order_id(log_entry)
        if order_id:
            if order_id in self.orders:
                self.orders[order_id]['exits'] += 1
                print(f"Order {order_id} exit logged.")
            else:
                print("Invalid order ID for exit.")
        else:
            print("Invalid log entry.")

    def get_order_status(self, order_id):
        if order_id in self.orders:
            return self.orders[order_id]
        else:
            return None

