from abc import ABC, abstractmethod

class PushNotificationInterface(ABC):
    @abstractmethod
    def send_notification(self, message, subscriber_id):
        pass

    @abstractmethod
    def log_notification(self, message, subscriber_id):
        pass

    @abstractmethod
    def manage_subscribers(self, action, subscriber_id):
        pass

class PushNotificationMeta(type):
    def __new__(cls, name, bases, dct):
        if not issubclass(PushNotificationInterface, dct.get('__mro__', ())):
            raise TypeError("Subclass must implement methods from PushNotificationInterface")
        return super().__new__(cls, name, bases, dct)

class PushNotificationService(metaclass=PushNotificationMeta):
    def send_notification(self, message, subscriber_id):
        # Implementation for sending notification
        print(f"Sending notification: {message} to subscriber: {subscriber_id}")

    def log_notification(self, message, subscriber_id):
        # Implementation for logging notification
        print(f"Logging notification: {message} for subscriber: {subscriber_id}")

    def manage_subscribers(self, action, subscriber_id):
        # Implementation for managing subscribers
        if action == "add":
            print(f"Adding subscriber: {subscriber_id}")
        elif action == "remove":
            print(f"Removing subscriber: {subscriber_id}")

