from abc import ABC, abstractmethod

class FraudDetectionMeta(type):
    def __new__(cls, name, bases, dct):
        required_methods = {'detect_fraud', 'prevent_fraud'}
        implemented_methods = {key for key in dct if callable(dct[key])}
        missing_methods = required_methods - implemented_methods

        if missing_methods:
            error_message = f"The class {name} must implement the following methods: {', '.join(missing_methods)}"
            raise TypeError(error_message)

        return super().__new__(cls, name, bases, dct)

class FraudDetectionRule(ABC, metaclass=FraudDetectionMeta):
    @abstractmethod
    def detect_fraud(self, data):
        pass

    @abstractmethod
    def prevent_fraud(self, data):
        pass

