import requests
from cryptography.fernet import Fernet

class InstantPayment:
    def __init__(self, api_key, encryption_key):
        self.api_key = api_key
        self.encryption_key = encryption_key
        self.cipher_suite = Fernet(encryption_key)

    def encrypt_data(self, data):
        return self.cipher_suite.encrypt(data.encode())

    def decrypt_data(self, encrypted_data):
        return self.cipher_suite.decrypt(encrypted_data).decode()

    def initiate_payment(self, amount, currency, recipient):
        payload = {
            'api_key': self.api_key,
            'amount': amount,
            'currency': currency,
            'recipient': recipient
        }
        encrypted_payload = {k: self.encrypt_data(v) for k, v in payload.items()}
        response = requests.post('https://paymentgateway.com/initiate', json=encrypted_payload)
        return response.json()

    def handle_transaction(self, transaction_id):
        response = requests.get(f'https://paymentgateway.com/transaction/{transaction_id}')
        encrypted_response = response.json()
        decrypted_response = {k: self.decrypt_data(v) for k, v in encrypted_response.items()}
        return decrypted_response

    def validate_payment_response(self, response):
        if response.get('status') == 'success':
            return True
        else:
            return False

