import threading

class MoneyManagementTool:
    def __init__(self):
        self.lock = threading.Lock()
        self.user_balances = {}
        self.transaction_history = {}

    def deposit(self, user_id, amount):
        with self.lock:
            if user_id not in self.user_balances:
                self.user_balances[user_id] = 0
            self.user_balances[user_id] += amount
            if user_id not in self.transaction_history:
                self.transaction_history[user_id] = []
            self.transaction_history[user_id].append(f"Deposited {amount}")

    def withdraw(self, user_id, amount):
        with self.lock:
            if user_id not in self.user_balances or self.user_balances[user_id] < amount:
                raise ValueError("Insufficient funds")
            self.user_balances[user_id] -= amount
            if user_id not in self.transaction_history:
                self.transaction_history[user_id] = []
            self.transaction_history[user_id].append(f"Withdrew {amount}")

    def transfer(self, from_user_id, to_user_id, amount):
        with self.lock:
            if from_user_id not in self.user_balances or self.user_balances[from_user_id] < amount:
                raise ValueError("Insufficient funds")
            self.user_balances[from_user_id] -= amount
            if to_user_id not in self.user_balances:
                self.user_balances[to_user_id] = 0
            self.user_balances[to_user_id] += amount
            if from_user_id not in self.transaction_history:
                self.transaction_history[from_user_id] = []
            if to_user_id not in self.transaction_history:
                self.transaction_history[to_user_id] = []
            self.transaction_history[from_user_id].append(f"Transferred {amount} to {to_user_id}")
            self.transaction_history[to_user_id].append(f"Received {amount} from {from_user_id}")

    def get_balance(self, user_id):
        with self.lock:
            return self.user_balances.get(user_id, 0)

    def get_transaction_history(self, user_id):
        with self.lock:
            return self.transaction_history.get(user_id, [])

