    def __init__(self, max_records=1000, purge_interval=timedelta(days=30)):
        self.max_records = max_records
        self.purge_interval = purge_interval
        self.records = collections.OrderedDict()
        self.last_purge = datetime.now()

    def add_record(self, payment_id, amount):
        current_time = datetime.now()
        if len(self.records) >= self.max_records:
            self.purge_old_records()
        self.records[payment_id] = PaymentRecord(payment_id, amount, current_time)

    def get_record(self, payment_id):
        if payment_id in self.records:
            self.records.move_to_end(payment_id)  # Move to end to mark as recently accessed
            return self.records[payment_id]
        return None

    def purge_old_records(self):
        current_time = datetime.now()
        if current_time - self.last_purge >= self.purge_interval:
            self.records = {k: v for k, v in self.records.items() if current_time - v.date < self.purge_interval}
            self.last_purge = current_time

# Example usage
