        if self.customer_data.empty:
            return False
        if not all(self.customer_data['age'].apply(lambda x: isinstance(x, int) and x >= 0)):
            return False
        if not all(self.customer_data['income'].apply(lambda x: isinstance(x, (int, float)) and x >= 0)):
            return False
        if not all(self.customer_data['credit_score'].apply(lambda x: isinstance(x, int) and 300 <= x <= 850)):
            return False
        return True

    def calculate_risk_score(self):
        if not self.validate_data():
            return None

        self.customer_data['risk_score'] = self.customer_data['age'] + self.customer_data['income'] + self.customer_data['credit_score']
        return self.customer_data['risk_score']

    def generate_underwriting_decisions(self):
        risk_scores = self.calculate_risk_score()
        if risk_scores is None:
            return None

        self.customer_data['underwriting_decision'] = risk_scores.apply(lambda x: 'Approve' if x < 1000 else 'Deny')
        return self.customer_data['underwriting_decision']

