class LoanApplicationMeta(type):
    def __new__(cls, name, bases, attrs):
        required_fields = {
            'loan_id': str,
            'borrower_name': str,
            'loan_amount': float,
            'interest_rate': float,
            'loan_term': int,
            'application_date': str,
            'status': str
        }
        for field, expected_type in required_fields.items():
            if field not in attrs:
                raise TypeError(f"{name} must include a '{field}' field.")
            if not isinstance(attrs[field], expected_type):
                raise TypeError(f"{field} must be of type {expected_type}.")
        return super().__new__(cls, name, bases, attrs)

