import re

class FraudDetectionSystem:
    def __init__(self):
        self.ip_pattern = re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b')
        self.card_pattern = re.compile(r'\b(?:\d{4}[- ]?){3}\d{4}\b')
        self.timestamp_pattern = re.compile(r'\b\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\b')

    def is_valid_ip(self, ip):
        return self.ip_pattern.match(ip) is not None

    def is_valid_card_number(self, card_number):
        return self.card_pattern.match(card_number) is not None

    def is_valid_timestamp(self, timestamp):
        return self.timestamp_pattern.match(timestamp) is not None

    def detect_fraudulent_transaction(self, transaction_data):
        if not self.is_valid_ip(transaction_data['ip_address']):
            return True, "Invalid IP address"
        if not self.is_valid_card_number(transaction_data['card_number']):
            return True, "Invalid card number"
        if not self.is_valid_timestamp(transaction_data['timestamp']):
            return True, "Invalid timestamp"
        return False, "No fraud detected"

import contextlib
import hashlib
import time

class DigitalCurrencyManager:
    def __init__(self, balance=0):
        self.balance = balance
        self.transactions = []

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self.balance += amount
        self.transactions.append((time.time(), "Deposit", amount))

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > self.balance:
            raise ValueError("Insufficient funds")
        self.balance -= amount
        self.transactions.append((time.time(), "Withdrawal", amount))

    @contextlib.contextmanager
    def transaction(self):
        try:
            yield
        except Exception as e:
            raise e
        finally:
            self.transactions.append((time.time(), "Transaction", self.balance))

    def get_balance(self):
        return self.balance

    def get_transactions(self):
        return self.transactions

    def hash_transactions(self):
        transaction_data = "\n".join(f"{timestamp},{action},{amount}" for timestamp, action, amount in self.transactions)
        return hashlib.sha256(transaction_data.encode()).hexdigest()

def calculate_tax(income):
    if income <= 10000:
        tax = 0
    elif income <= 50000:
        tax = (income - 10000) * 0.10
    else:
        tax = (50000 - 10000) * 0.10 + (income - 50000) * 0.20
    return tax

