class MobileCheckDepositLimits:
    def __init__(self, api_url, api_key):
        self.api_url = api_url
        self.api_key = api_key
        self.limits_df = pd.DataFrame(columns=['user_id', 'limit'])

    def fetch_limits(self):
        headers = {'Authorization': f'Bearer {self.api_key}'}
        response = requests.get(f'{self.api_url}/limits', headers=headers)
        if response.status_code == 200:
            self.limits_df = pd.DataFrame(response.json())
        else:
            raise Exception(f"Failed to fetch limits: {response.status_code}")

    def validate_input(self, user_id, limit):
        if not isinstance(user_id, int) or not isinstance(limit, (int, float)):
            raise ValueError("User ID must be an integer and limit must be a number.")
        if limit < 0:
            raise ValueError("Deposit limit cannot be negative.")

    def check_limit(self, user_id):
        user_limit = self.limits_df.loc[self.limits_df['user_id'] == user_id, 'limit'].values
        if len(user_limit) == 0:
            return None
        return user_limit[0]

    def update_limit(self, user_id, new_limit):
        self.validate_input(user_id, new_limit)
        user_limit = self.check_limit(user_id)
        if user_limit is None:
            self.limits_df = self.limits_df.append({'user_id': user_id, 'limit': new_limit}, ignore_index=True)
        else:
            self.limits_df.loc[self.limits_df['user_id'] == user_id, 'limit'] = new_limit
        self.update_backend(user_id, new_limit)

    def update_backend(self, user_id, new_limit):
        headers = {'Authorization': f'Bearer {self.api_key}', 'Content-Type': 'application/json'}
        payload = {'user_id': user_id, 'limit': new_limit}
        response = requests.put(f'{self.api_url}/limits/{user_id}', headers=headers, json=payload)
        if response.status_code != 200:
            raise Exception(f"Failed to update limit for user {user_id}: {response.status_code}")

import threading
import queue
import time
import random

class FinancialTransactionProcessor:
    def __init__(self, num_threads):
        self.num_threads = num_threads
        self.transaction_queue = queue.Queue()
        self.threads = []
        self.lock = threading.Lock()

    def add_transaction(self, transaction):
        with self.lock:
            self.transaction_queue.put(transaction)

    def process_transaction(self, transaction):
        # Simulate transaction processing
        time.sleep(random.uniform(0.1, 0.5))
        print(f"Processed transaction: {transaction}")

    def start(self):
        for _ in range(self.num_threads):
            thread = threading.Thread(target=self.worker)
            thread.start()
            self.threads.append(thread)

    def worker(self):
        while True:
            transaction = self.transaction_queue.get()
            if transaction is None:
                break
            self.process_transaction(transaction)
            self.transaction_queue.task_done()

    def stop(self):
        for _ in range(self.num_threads):
            self.transaction_queue.put(None)
        for thread in self.threads:
            thread.join()

