import re

class PhishingDetector:
    def __init__(self):
        # Define a list of common phishing keywords
        self.phishing_keywords = [
            'click here', 'act now', 'verify your account', 'urgent action required',
            'win money', 'prize alert', 'refund request', 'account suspension', 'free trial'
        ]
        # Define a pattern to match URLs
        self.url_pattern = re.compile(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+')

    def detect_phishing(self, email_text):
        # Convert the email text to lowercase for case-insensitive comparison
        email_text = email_text.lower()

        # Check for phishing keywords
        for keyword in self.phishing_keywords:
            if keyword in email_text:
                return True

        # Check for URLs
        if self.url_pattern.search(email_text):
            return True

        # Check for suspicious email addresses
        suspicious_emails = re.findall(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', email_text)
        for email in suspicious_emails:
            if email.endswith('@example.com') or email.endswith('@test.com'):
                return True

        return False

