class RealTimeAlertSystem:
    def __init__(self):
        self.users = {}
        self.alerts = {}

    class User:
        def __init__(self, user_id, device_id):
            self.user_id = user_id
            self.device_id = device_id
            self.alert_subscriptions = []

    class Alert:
        def __init__(self, alert_id, user_id, alert_type, details):
            self.alert_id = alert_id
            self.user_id = user_id
            self.alert_type = alert_type
            self.details = details

    def subscribe_user(self, user_id, device_id):
        if user_id not in self.users:
            self.users[user_id] = self.User(user_id, device_id)
        self.users[user_id].alert_subscriptions.append(device_id)

    def unsubscribe_user(self, user_id, device_id):
        if user_id in self.users:
            if device_id in self.users[user_id].alert_subscriptions:
                self.users[user_id].alert_subscriptions.remove(device_id)
            if not self.users[user_id].alert_subscriptions:
                del self.users[user_id]

    def trigger_alert(self, user_id, alert_type, details):
        if user_id in self.users:
            alert_id = len(self.alerts) + 1
            alert = self.Alert(alert_id, user_id, alert_type, details)
            self.alerts[alert_id] = alert
            for device_id in self.users[user_id].alert_subscriptions:
                print(f"Alert {alert_id} triggered for user {user_id} on device {device_id}: {alert_type} - {details}")

