# Define a class to represent a user in the P2P payment system
class User:
    def __init__(self, name):
        self.name = name
        self.balance = 0.0

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"{self.name} deposited ${amount}. New balance: ${self.balance}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        if 0 < amount <= self.balance:
            self.balance -= amount
            print(f"{self.name} withdrew ${amount}. New balance: ${self.balance}")
        else:
            print("Insufficient funds or invalid withdrawal amount.")

    def get_balance(self):
        return self.balance

# Define a class to represent a transaction in the P2P payment system
class Transaction:
    def __init__(self, sender, receiver, amount, timestamp):
        self.sender = sender
        self.receiver = receiver
        self.amount = amount
        self.timestamp = timestamp

    def display_transaction(self):
        print(f"Transaction from {self.sender} to {self.receiver}: ${self.amount} at {self.timestamp}")

# Define a class to represent the P2P payment system
class P2PSystem:
    def __init__(self):
        self.users = {}
        self.transactions = []

    def add_user(self, name):
        if name not in self.users:
            self.users[name] = User(name)
            print(f"User {name} added.")
        else:
            print(f"User {name} already exists.")

    def record_transaction(self, sender, receiver, amount):
        if sender in self.users and receiver in self.users:
            if amount > 0:
                sender_user = self.users[sender]
                receiver_user = self.users[receiver]
                sender_user.withdraw(amount)
                receiver_user.deposit(amount)
                transaction = Transaction(sender, receiver, amount, datetime.datetime.now())
                self.transactions.append(transaction)
                print(f"Transaction recorded: {sender} sent ${amount} to {receiver}.")
            else:
                print("Transaction amount must be positive.")
        else:
            print("Sender or receiver user does not exist.")

    def display_transactions(self):
        for transaction in self.transactions:
            transaction.display_transaction()

# Example usage
p2p_system = P2PSystem()
p2p_system.add_user("Alice")
p2p_system.add_user("Bob")
p2p_system.record_transaction("Alice", "Bob", 100.0)
p2p_system.display_transactions()

from datetime import datetime, timedelta

class PolicyCancellationMeta(type):
    def __new__(cls, name, bases, dct):
        original_cancel = dct.get('cancel_policy')

        def cancel_policy(self, reason):
            if not self.can_cancel():
                raise ValueError("Policy cannot be canceled at this time.")
            if reason not in self.valid_cancellation_reasons:
                raise ValueError("Invalid cancellation reason.")
            return original_cancel(self, reason)

        dct['cancel_policy'] = cancel_policy
        return super().__new__(cls, name, bases, dct)

class InsurancePolicy(metaclass=PolicyCancellationMeta):
    def __init__(self, policy_id, start_date, end_date, valid_cancellation_reasons):
        self.policy_id = policy_id
        self.start_date = start_date
        self.end_date = end_date
        self.valid_cancellation_reasons = valid_cancellation_reasons

    def can_cancel(self):
        today = datetime.now()
        return today < self.end_date - timedelta(days=30)

    def cancel_policy(self, reason):
        # Logic to cancel the policy
        print(f"Policy {self.policy_id} canceled due to reason: {reason}")

# Example usage
