class InsurancePolicy:
    def __init__(self, policy_id, policy_type, premium, discount=None, surcharge=None):
        self.policy_id = policy_id
        self.policy_type = policy_type
        self.premium = premium
        self.discount = discount if discount is not None else 0
        self.surcharge = surcharge if surcharge is not None else 0

    def update_premium(self, new_premium):
        self.premium = new_premium

    def update_discount(self, new_discount):
        self.discount = new_discount

    def update_surcharge(self, new_surcharge):
        self.surcharge = new_surcharge

    def calculate_total_premium(self):
        total_premium = self.premium - (self.premium * self.discount / 100) + (self.premium * self.surcharge / 100)
        return total_premium

class PolicyManager:
    def __init__(self):
        self.policies = {}

    def add_policy(self, policy):
        self.policies[policy.policy_id] = policy

    def update_policy(self, policy_id, **kwargs):
        if policy_id in self.policies:
            for key, value in kwargs.items():
                if hasattr(self.policies[policy_id], key):
                    setattr(self.policies[policy_id], key, value)

    def delete_policy(self, policy_id):
        if policy_id in self.policies:
            del self.policies[policy_id]

    def calculate_total_premiums(self):
        total_premiums = sum(policy.calculate_total_premium() for policy in self.policies.values())
        return total_premiums

