class CreditScoreHistory:
    def __init__(self):
        self.scores = {}

    def add_score(self, user_id, score, date):
        if user_id not in self.scores:
            self.scores[user_id] = []
        self.scores[user_id].append((date, score))

    def update_score(self, user_id, score, date):
        if user_id in self.scores:
            self.scores[user_id] = [(d, s if d != date else score) for d, s in self.scores[user_id]]

    def average_score(self, user_id, start_date, end_date):
        if user_id in self.scores:
            relevant_scores = [s for d, s in self.scores[user_id] if start_date <= d <= end_date]
            if relevant_scores:
                return sum(relevant_scores) / len(relevant_scores)
        return None

