class OrderExecutor:
    def __init__(self):
        # Initialize an empty dictionary to store order status
        self.orders = {}

    def place_buy_order(self, order_id, symbol, quantity, price):
        """
        Place a buy order for a given stock symbol with the specified quantity and price.
        """
        if order_id in self.orders:
            print(f"Order {order_id} already exists.")
        else:
            self.orders[order_id] = {
                'symbol': symbol,
                'quantity': quantity,
                'price': price,
                'type': 'buy'
            }
            print(f"Buy order {order_id} placed for {symbol} with quantity {quantity} at price {price}.")

    def place_sell_order(self, order_id, symbol, quantity, price):
        """
        Place a sell order for a given stock symbol with the specified quantity and price.
        """
        if order_id in self.orders:
            print(f"Order {order_id} already exists.")
        else:
            self.orders[order_id] = {
                'symbol': symbol,
                'quantity': quantity,
                'price': price,
                'type': 'sell'
            }
            print(f"Sell order {order_id} placed for {symbol} with quantity {quantity} at price {price}.")

    def check_order_status(self, order_id):
        """
        Check the status of a given order.
        """
        if order_id in self.orders:
            order = self.orders[order_id]
            status = "Filled" if order['type'] == 'buy' else "Open"
            print(f"Order {order_id} for {order['symbol']} is {status}.")
        else:
            print(f"Order {order_id} not found.")

