import hashlib
from collections import defaultdict

class DeviceFingerprintAnalyzer:
    def __init__(self):
        self.fingerprints = defaultdict(list)
        self.fingerprint_scores = {}

    def add_fingerprint(self, device_id, fingerprint_data):
        fingerprint_hash = self._hash_fingerprint(fingerprint_data)
        self.fingerprints[device_id].append(fingerprint_hash)
        self.fingerprint_scores[device_id] = self._calculate_score(device_id)

    def update_fingerprint(self, device_id, new_fingerprint_data):
        self.remove_fingerprint(device_id)
        self.add_fingerprint(device_id, new_fingerprint_data)

    def remove_fingerprint(self, device_id):
        if device_id in self.fingerprints:
            del self.fingerprints[device_id]
            del self.fingerprint_scores[device_id]

    def detect_fraud(self, device_id):
        if device_id in self.fingerprint_scores and self.fingerprint_scores[device_id] > 0.5:
            return True
        return False

    def _hash_fingerprint(self, fingerprint_data):
        return hashlib.sha256(fingerprint_data.encode()).hexdigest()

    def _calculate_score(self, device_id):
        fingerprints = self.fingerprints[device_id]
        if len(fingerprints) < 2:
            return 0.0
        unique_fingerprints = len(set(fingerprints))
        score = (1 - unique_fingerprints / len(fingerprints)) * 100
        return score / 100.0

# Example usage
analyzer = DeviceFingerprintAnalyzer()
analyzer.add_fingerprint("user123", "device_info_1")
analyzer.add_fingerprint("user123", "device_info_2")
analyzer.add_fingerprint("user456", "device_info_1")
print(analyzer.detect_fraud("user123"))  # Output: False
print(analyzer.detect_fraud("user456"))  # Output: True

import threading

class AccountIDMeta(type):
    _account_ids = {}
    _lock = threading.Lock()

    def __call__(cls, *args, **kwargs):
        with cls._lock:
            if cls not in cls._account_ids:
                cls._account_ids[cls] = 0
            cls._account_ids[cls] += 1
            return cls._account_ids[cls]

class Account(metaclass=AccountIDMeta):
    pass

