import sqlite3
from contextlib import contextmanager

class VirtualCurrencyTransaction:
    def __init__(self, db_path):
        self.db_path = db_path

    @contextmanager
    def _db_connection(self):
        conn = sqlite3.connect(self.db_path)
        try:
            yield conn
        finally:
            conn.close()

    def add_transaction(self, transaction_id, sender, receiver, amount, timestamp):
        with self._db_connection() as conn:
            cursor = conn.cursor()
            cursor.execute(
                """
                INSERT INTO transactions (transaction_id, sender, receiver, amount, timestamp)
                VALUES (?, ?, ?, ?, ?)
                """,
                (transaction_id, sender, receiver, amount, timestamp)
            )
            conn.commit()

    def get_transaction(self, transaction_id):
        with self._db_connection() as conn:
            cursor = conn.cursor()
            cursor.execute(
                """
                SELECT * FROM transactions WHERE transaction_id = ?
                """,
                (transaction_id,)
            )
            return cursor.fetchone()

    def list_transactions(self, sender=None, receiver=None):
        with self._db_connection() as conn:
            cursor = conn.cursor()
            if sender and receiver:
                cursor.execute(
                    """
                    SELECT * FROM transactions WHERE sender = ? AND receiver = ?
                    """,
                    (sender, receiver)
                )
            elif sender:
                cursor.execute(
                    """
                    SELECT * FROM transactions WHERE sender = ?
                    """,
                    (sender,)
                )
            elif receiver:
                cursor.execute(
                    """
                    SELECT * FROM transactions WHERE receiver = ?
                    """,
                    (receiver,)
                )
            else:
                cursor.execute(
                    """
                    SELECT * FROM transactions
                    """
                )
            return cursor.fetchall()

from flask import Flask, request, jsonify
import requests

class AutomatedOrderExecution:
    def __init__(self, exchange_api_url, api_key, api_secret):
        self.exchange_api_url = exchange_api_url
        self.api_key = api_key
        self.api_secret = api_secret

    def place_order(self, symbol, quantity, side, order_type):
        headers = {
            'Content-Type': 'application/json',
            'X-API-KEY': self.api_key,
            'X-API-SECRET': self.api_secret
        }
        data = {
            'symbol': symbol,
            'quantity': quantity,
            'side': side,
            'type': order_type
        }
        response = requests.post(f"{self.exchange_api_url}/order", headers=headers, json=data)
        return response.json()

    def cancel_order(self, order_id):
        headers = {
            'Content-Type': 'application/json',
            'X-API-KEY': self.api_key,
            'X-API-SECRET': self.api_secret
        }
        response = requests.delete(f"{self.exchange_api_url}/order/{order_id}", headers=headers)
        return response.json()

    def get_order_status(self, order_id):
        headers = {
            'Content-Type': 'application/json',
            'X-API-KEY': self.api_key,
            'X-API-SECRET': self.api_secret
        }
        response = requests.get(f"{self.exchange_api_url}/order/{order_id}", headers=headers)
        return response.json()

app = Flask(__name__)

@app.route('/place_order', methods=['POST'])
def place_order_route():
    data = request.json
    order = AutomatedOrderExecution(
        exchange_api_url=data['exchange_api_url'],
        api_key=data['api_key'],
        api_secret=data['api_secret']
    )
    result = order.place_order(
        symbol=data['symbol'],
        quantity=data['quantity'],
        side=data['side'],
        order_type=data['order_type']
    )
    return jsonify(result)

@app.route('/cancel_order', methods=['POST'])
def cancel_order_route():
    data = request.json
    order = AutomatedOrderExecution(
        exchange_api_url=data['exchange_api_url'],
        api_key=data['api_key'],
        api_secret=data['api_secret']
    )
    result = order.cancel_order(data['order_id'])
    return jsonify(result)

@app.route('/get_order_status', methods=['POST'])
def get_order_status_route():
    data = request.json
    order = AutomatedOrderExecution(
        exchange_api_url=data['exchange_api_url'],
        api_key=data['api_key'],
        api_secret=data['api_secret']
    )
    result = order.get_order_status(data['order_id'])
    return jsonify(result)

if __name__ == '__main__':
    app.run(debug=True)

