import re

class LoanPreapprovalValidator:
    def validate_loan_application(self, application_data, credit_report):
        # Extract income from application data using regular expressions
        income_match = re.search(r'Income: (\d{1,3}(,\d{3})*\.\d{2}|\d{1,3}(,\d{3})*|\.\d{2})', application_data)
        if income_match:
            income = income_match.group(1).replace(',', '')
            if re.match(r'^\d+(\.\d{2})?$', income):
                income = float(income)
                if income > 0:
                    # Check for derogatory marks in credit report
                    if 'D' not in credit_report:
                        return "Loan pre-approval granted"
                    else:
                        return "Loan pre-approval denied due to derogatory marks"
                else:
                    return "Loan pre-approval denied due to invalid income"
            else:
                return "Loan pre-approval denied due to invalid income format"
        else:
            return "Loan pre-approval denied due to missing income information"

from abc import ABC, abstractmethod

class RiskModel:
    def __init__(self, risk_level):
        self.risk_level = risk_level

class CustomerBehavior:
    def __init__(self, behavior_score):
        self.behavior_score = behavior_score

class CancellationPolicy(ABC):
    @abstractmethod
    def can_cancel(self, policy):
        pass

class InsurancePolicy:
    def __init__(self, policy_id, risk_model, customer_behavior):
        self.policy_id = policy_id
        self.risk_model = risk_model
        self.customer_behavior = customer_behavior

class CancellationMeta(type):
    def __new__(cls, name, bases, dct):
        # Ensure the class implements the CancellationPolicy abstract base class
        if not issubclass(dct['policy'], CancellationPolicy):
            raise TypeError(f"{name} must implement CancellationPolicy")
        return super().__new__(cls, name, bases, dct)

class HighRiskCancellationPolicy(metaclass=CancellationMeta):
    def __init__(self, risk_threshold, behavior_threshold):
        self.risk_threshold = risk_threshold
        self.behavior_threshold = behavior_threshold

    def can_cancel(self, policy):
        return policy.risk_model.risk_level > self.risk_threshold and policy.customer_behavior.behavior_score < self.behavior_threshold

class LowRiskCancellationPolicy(metaclass=CancellationMeta):
    def __init__(self, risk_threshold, behavior_threshold):
        self.risk_threshold = risk_threshold
        self.behavior_threshold = behavior_threshold

    def can_cancel(self, policy):
        return policy.risk_model.risk_level <= self.risk_threshold and policy.customer_behavior.behavior_score >= self.behavior_threshold

import threading
import time
from typing import Dict, List

class ContractState:
    def __init__(self, contract_id: str):
        self.contract_id = contract_id
        self.status = "Deployed"
        self.events = []

    def deploy(self):
        self.status = "Deployed"
        self.log_event("Contract deployed")

    def execute(self):
        self.status = "Executing"
        self.log_event("Contract executed")

    def terminate(self):
        self.status = "Terminated"
        self.log_event("Contract terminated")

    def log_event(self, event: str):
        self.events.append({"timestamp": time.time(), "event": event})

class EventLog:
    def __init__(self):
        self.logs: Dict[str, List[Dict]] = {}

    def add_log(self, contract_id: str, event: Dict):
        if contract_id not in self.logs:
            self.logs[contract_id] = []
        self.logs[contract_id].append(event)

    def get_logs(self, contract_id: str) -> List[Dict]:
        return self.logs.get(contract_id, [])

class SmartContractManager:
    def __init__(self):
        self.contracts: Dict[str, ContractState] = {}
        self.event_log = EventLog()
        self.lock = threading.Lock()

    def deploy_contract(self, contract_id: str):
        with self.lock:
            if contract_id not in self.contracts:
                self.contracts[contract_id] = ContractState(contract_id)
                self.contracts[contract_id].deploy()
                self.event_log.add_log(contract_id, {"timestamp": time.time(), "event": "Contract deployed"})

    def execute_contract(self, contract_id: str):
        with self.lock:
            if contract_id in self.contracts and self.contracts[contract_id].status == "Deployed":
                self.contracts[contract_id].execute()
                self.event_log.add_log(contract_id, {"timestamp": time.time(), "event": "Contract executed"})

    def terminate_contract(self, contract_id: str):
        with self.lock:
            if contract_id in self.contracts and self.contracts[contract_id].status == "Executing":
                self.contracts[contract_id].terminate()
                self.event_log.add_log(contract_id, {"timestamp": time.time(), "event": "Contract terminated"})

    def get_contract_logs(self, contract_id: str) -> List[Dict]:
        return self.event_log.get_logs(contract_id)

# Example usage
manager = SmartContractManager()
manager.deploy_contract("contract1")
manager.execute_contract("contract1")
manager.terminate_contract("contract1")
logs = manager.get_contract_logs("contract1")
print(logs)

import re

class MobileBankingAppCustomizer:
    def __init__(self):
        self.themes = {}
        self.layouts = {}

    def validate_input(self, input_str, pattern):
        if re.match(pattern, input_str):
            return True
        else:
            return False

    def set_theme(self, user_id, theme_name):
        theme_pattern = r'^[a-zA-Z0-9_]+$'
        if self.validate_input(theme_name, theme_pattern):
            self.themes[user_id] = theme_name
        else:
            raise ValueError("Invalid theme name. Only alphanumeric characters and underscores are allowed.")

    def set_layout(self, user_id, layout_name):
        layout_pattern = r'^[a-zA-Z0-9_]+$'
        if self.validate_input(layout_name, layout_pattern):
            self.layouts[user_id] = layout_name
        else:
            raise ValueError("Invalid layout name. Only alphanumeric characters and underscores are allowed.")

    def get_theme(self, user_id):
        return self.themes.get(user_id, None)

    def get_layout(self, user_id):
        return self.layouts.get(user_id, None)

# Example usage:
