import uuid

class TransactionIDMeta(type):
    _transaction_ids = set()

    def __call__(cls, *args, **kwargs):
        transaction_id = cls._generate_unique_id()
        while transaction_id in cls._transaction_ids:
            transaction_id = cls._generate_unique_id()
        cls._transaction_ids.add(transaction_id)
        instance = super().__call__(*args, **kwargs)
        instance.transaction_id = transaction_id
        return instance

    @staticmethod
    def _generate_unique_id():
        return str(uuid.uuid4())

