from collections import OrderedDict, Counter
from typing import Any, Dict, Hashable, Optional

class LRUCache:
    def __init__(self, capacity: int):
        self.cache: OrderedDict[Hashable, Any] = OrderedDict()
        self.capacity = capacity

    def get(self, key: Hashable) -> Optional[Any]:
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: Hashable, value: Any) -> None:
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

class LFUCache:
    def __init__(self, capacity: int):
        self.cache: Dict[Hashable, Any] = {}
        self.frequency: Counter[Hashable] = Counter()
        self.min_freq = 0
        self.capacity = capacity

    def get(self, key: Hashable) -> Optional[Any]:
        if key not in self.cache:
            return None
        self.frequency[key] += 1
        self.cache[key] = self.cache.pop(key)
        self.update_min_freq()
        return self.cache[key]

    def put(self, key: Hashable, value: Any) -> None:
        if key in self.cache:
            self.cache[key] = value
            self.frequency[key] += 1
            self.cache[key] = self.cache.pop(key)
            self.update_min_freq()
            return
        if len(self.cache) >= self.capacity:
            evict_key = min(self.cache, key=lambda k: (self.frequency[k], k))
            self.cache.pop(evict_key)
            self.frequency.pop(evict_key)
        self.cache[key] = value
        self.frequency[key] = 1
        self.min_freq = 1

    def update_min_freq(self) -> None:
        if self.min_freq not in self.frequency:
            self.min_freq += 1

