            r'^SELL \d+ @ \d+\.\d{2}$': 'Exchange B',
            r'^LIMIT BUY \d+ @ \d+\.\d{2}$': 'Exchange C',
            r'^LIMIT SELL \d+ @ \d+\.\d{2}$': 'Exchange D'
