class BankAccountTaxCalculator:
    def __init__(self):
        self.transactions = None
        self.tax_rates = {
            'Deposit': 0.01,
            'Withdrawal': 0.02,
            'Interest': 0.005
        }

    def load_transactions(self, file_path):
        self.transactions = pd.read_csv(file_path)

    def filter_transactions(self, date_range=None, transaction_type=None):
        if self.transactions is None:
            raise ValueError("Transactions not loaded yet.")

        filtered = self.transactions.copy()
        if date_range:
            filtered = filtered[(filtered['date'] >= date_range[0]) & (filtered['date'] <= date_range[1])]
        if transaction_type:
            filtered = filtered[filtered['transaction_type'] == transaction_type]

        return filtered

    def compute_tax(self):
        if self.transactions is None:
            raise ValueError("Transactions not loaded yet.")

        self.transactions['tax'] = self.transactions.apply(
            lambda row: row['amount'] * self.tax_rates.get(row['transaction_type'], 0), axis=1
        )
        return self.transactions

