dao.set_state('balance', 1000)
print(dao.get_state('balance'))  # Output: 1000
dao.delete_state('balance')
print(dao.get_state('balance'))  # Output: None
dao.save_state('dao_state.pkl')
dao.load_state('dao_state.pkl')
