import boto3
from botocore.exceptions import ClientError

class PolicyDocumentManager:
    def __init__(self, s3_bucket_name, lambda_function_name):
        self.s3_client = boto3.client('s3')
        self.lambda_client = boto3.client('lambda')
        self.s3_bucket_name = s3_bucket_name
        self.lambda_function_name = lambda_function_name

    def upload_document(self, policy_id, file_path):
        try:
            self.s3_client.upload_file(file_path, self.s3_bucket_name, policy_id)
            self.lambda_client.invoke(
                FunctionName=self.lambda_function_name,
                InvocationType='Event',
                Payload=f'{{"policy_id": "{policy_id}", "action": "upload"}}'
            )
            return f"Document {policy_id} uploaded successfully."
        except ClientError as e:
            return f"Error uploading document: {e}"

    def retrieve_document(self, policy_id):
        try:
            response = self.s3_client.get_object(Bucket=self.s3_bucket_name, Key=policy_id)
            return response['Body'].read()
        except ClientError as e:
            return f"Error retrieving document: {e}"

    def update_document_status(self, policy_id, status):
        try:
            self.lambda_client.invoke(
                FunctionName=self.lambda_function_name,
                InvocationType='Event',
                Payload=f'{{"policy_id": "{policy_id}", "action": "update", "status": "{status}"}}'
            )
            return f"Document {policy_id} status updated to {status}."
        except ClientError as e:
            return f"Error updating document status: {e}"

import threading
import time

class BudgetCategory:
    def __init__(self, name, limit):
        self.name = name
        self.limit = limit
        self.current_spending = 0
        self.lock = threading.Lock()

    def add_spending(self, amount):
        with self.lock:
            if self.current_spending + amount > self.limit:
                raise ValueError("Spending exceeds budget limit")
            self.current_spending += amount

    def get_spending(self):
        with self.lock:
            return self.current_spending

class UserAccount:
    def __init__(self, user_id):
        self.user_id = user_id
        self.budget_categories = {}
        self.transactions = []

    def add_budget_category(self, category_name, limit):
        if category_name in self.budget_categories:
            raise ValueError("Budget category already exists")
        self.budget_categories[category_name] = BudgetCategory(category_name, limit)

    def add_transaction(self, category_name, amount):
        if category_name not in self.budget_categories:
            raise ValueError("Budget category does not exist")
        self.budget_categories[category_name].add_spending(amount)
        self.transactions.append((time.time(), category_name, amount))

    def get_budget_category_spending(self, category_name):
        if category_name not in self.budget_categories:
            raise ValueError("Budget category does not exist")
        return self.budget_categories[category_name].get_spending()

class BudgetTrackingSystem:
    def __init__(self):
        self.user_accounts = {}
        self.lock = threading.Lock()

    def create_user_account(self, user_id):
        if user_id in self.user_accounts:
            raise ValueError("User account already exists")
        self.user_accounts[user_id] = UserAccount(user_id)

    def add_budget_category(self, user_id, category_name, limit):
        with self.lock:
            if user_id not in self.user_accounts:
                raise ValueError("User account does not exist")
            self.user_accounts[user_id].add_budget_category(category_name, limit)

    def add_transaction(self, user_id, category_name, amount):
        with self.lock:
            if user_id not in self.user_accounts:
                raise ValueError("User account does not exist")
            self.user_accounts[user_id].add_transaction(category_name, amount)

    def get_budget_category_spending(self, user_id, category_name):
        with self.lock:
            if user_id not in self.user_accounts:
                raise ValueError("User account does not exist")
            return self.user_accounts[user_id].get_budget_category_spending(category_name)

from flask import Flask, request, jsonify, abort
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash
from datetime import datetime
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///banking.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(120), nullable=False)
    transactions = db.relationship('Transaction', backref='user', lazy=True)

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

class Transaction(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    amount = db.Column(db.Float, nullable=False)
    description = db.Column(db.String(200))
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if User.query.filter_by(username=data['username']).first():
        abort(409)
    user = User(username=data['username'])
    user.set_password(data['password'])
    db.session.add(user)
    db.session.commit()
    return jsonify({'message': 'User created successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    user = User.query.filter_by(username=data['username']).first()
    if user and user.check_password(data['password']):
        return jsonify({'message': 'Login successful'}), 200
    abort(401)

@app.route('/transactions', methods=['POST'])
def create_transaction():
    data = request.get_json()
    user = User.query.filter_by(username=data['username']).first()
    if not user:
        abort(404)
    transaction = Transaction(amount=data['amount'], description=data['description'], user=user)
    db.session.add(transaction)
    db.session.commit()
    return jsonify({'message': 'Transaction created successfully'}), 201

@app.route('/transactions', methods=['GET'])
def get_transactions():
    user = User.query.filter_by(username=request.args.get('username')).first()
    if not user:
        abort(404)
    transactions = user.transactions
    return jsonify([{'id': t.id, 'amount': t.amount, 'description': t.description, 'timestamp': t.timestamp} for t in transactions]), 200

