from collections import deque

class ATMTransactionQueue:
    def __init__(self):
        self.queue = deque()
        self.priority_levels = {
            'cash_withdrawal': 1,
            'deposit': 2,
            'balance_inquiry': 3
        }

    def enqueue(self, transaction):
        self.queue.append(transaction)

    def dequeue(self):
        if not self.queue:
            return None
        return self.queue.popleft()

    def size(self):
        return len(self.queue)

    def is_empty(self):
        return self.size() == 0

    def peek(self):
        if not self.queue:
            return None
        return self.queue[0]

    def sort_queue(self):
        self.queue = deque(sorted(self.queue, key=lambda x: self.priority_levels[x['type']]))

# Example usage
atm_queue = ATMTransactionQueue()
atm_queue.enqueue({'id': 1, 'type': 'balance_inquiry'})
atm_queue.enqueue({'id': 2, 'type': 'cash_withdrawal'})
atm_queue.enqueue({'id': 3, 'type': 'deposit'})

print("Original Queue:")
while not atm_queue.is_empty():
    print(atm_queue.dequeue())

atm_queue.enqueue({'id': 1, 'type': 'balance_inquiry'})
atm_queue.enqueue({'id': 2, 'type': 'cash_withdrawal'})
atm_queue.enqueue({'id': 3, 'type': 'deposit'})

atm_queue.sort_queue()

print("\nSorted Queue:")
while not atm_queue.is_empty():
    print(atm_queue.dequeue())

import pandas as pd
from datetime import datetime

class BankAccountManager:
    def __init__(self):
        self.transactions = pd.DataFrame(columns=['Date', 'Type', 'Amount', 'Balance'])

    def add_transaction(self, transaction_type, amount):
        if transaction_type not in ['Deposit', 'Withdrawal']:
            raise ValueError("Transaction type must be 'Deposit' or 'Withdrawal'")
        if self.transactions.empty:
            new_balance = amount
        else:
            new_balance = self.transactions['Balance'].iloc[-1] + amount
        new_transaction = pd.DataFrame({
            'Date': [datetime.now()],
            'Type': [transaction_type],
            'Amount': [amount],
            'Balance': [new_balance]
        })
        self.transactions = pd.concat([self.transactions, new_transaction], ignore_index=True)

    def update_transaction(self, index, transaction_type, amount):
        if transaction_type not in ['Deposit', 'Withdrawal']:
            raise ValueError("Transaction type must be 'Deposit' or 'Withdrawal'")
        if index < 0 or index >= len(self.transactions):
            raise IndexError("Transaction index out of range")
        new_balance = self.transactions['Balance'].iloc[index] + amount
        self.transactions.at[index, 'Type'] = transaction_type
        self.transactions.at[index, 'Amount'] = amount
        self.transactions.at[index, 'Balance'] = new_balance

    def generate_summary_report(self, start_date, end_date):
        if start_date > end_date:
            raise ValueError("Start date must be before end date")
        filtered_transactions = self.transactions[(self.transactions['Date'] >= start_date) & (self.transactions['Date'] <= end_date)]
        return filtered_transactions

