import threading
import time
from queue import Queue

class LoanForbearanceSystem:
    def __init__(self, num_workers=5):
        self.loan_queue = Queue()
        self.num_workers = num_workers
        self.threads = []
        self.start_workers()

    def start_workers(self):
        for _ in range(self.num_workers):
            thread = threading.Thread(target=self.worker)
            thread.start()
            self.threads.append(thread)

    def worker(self):
        while True:
            loan = self.loan_queue.get()
            if loan is None:
                break
            self.process_loan(loan)
            self.loan_queue.task_done()

    def process_loan(self, loan):
        # Simulate loan processing
        print(f"Processing loan {loan['id']} for forbearance")
        time.sleep(1)
        print(f"Loan {loan['id']} processed")

    def initiate_forbearance(self, loan_id, duration):
        loan = {'id': loan_id, 'status': 'pending', 'forbearance_duration': duration}
        self.loan_queue.put(loan)
        print(f"Forbearance request initiated for loan {loan_id}")

    def manage_forbearance_periods(self):
        while not self.loan_queue.empty():
            loan = self.loan_queue.get()
            if loan['status'] == 'pending':
                loan['status'] = 'in_progress'
                print(f"Forbearance for loan {loan['id']} started for {loan['forbearance_duration']} days")
                time.sleep(loan['forbearance_duration'])
                loan['status'] = 'completed'
                print(f"Forbearance for loan {loan['id']} completed")
            self.loan_queue.task_done()

    def update_loan_statuses(self):
        while not self.loan_queue.empty():
            loan = self.loan_queue.get()
            if loan['status'] == 'in_progress':
                print(f"Loan {loan['id']} status updated to completed")
                loan['status'] = 'completed'
            self.loan_queue.task_done()

# Example usage
