class InvestmentPortfolio:
    def __init__(self):
        self.investments = {}

    def add_investment(self, investment_name, quantity, price_per_unit):
        if investment_name in self.investments:
            self.investments[investment_name]['quantity'] += quantity
            self.investments[investment_name]['total_value'] += quantity * price_per_unit
        else:
            self.investments[investment_name] = {
                'quantity': quantity,
                'price_per_unit': price_per_unit,
                'total_value': quantity * price_per_unit
            }

    def remove_investment(self, investment_name, quantity):
        if investment_name in self.investments:
            if self.investments[investment_name]['quantity'] >= quantity:
                self.investments[investment_name]['quantity'] -= quantity
                self.investments[investment_name]['total_value'] -= quantity * self.investments[investment_name]['price_per_unit']
                if self.investments[investment_name]['quantity'] == 0:
                    del self.investments[investment_name]
            else:
                raise ValueError("Not enough quantity to remove")
        else:
            raise KeyError("Investment not found in portfolio")

    def calculate_total_value(self):
        total_value = sum(investment['total_value'] for investment in self.investments.values())
        return total_value

