class FungibleTokenManager:
    def __init__(self, token_name, total_supply):
        self.token_name = token_name
        self.total_supply = total_supply
        self.balances = {}
        self.events = []

    def transfer(self, from_address, to_address, amount):
        if from_address not in self.balances or self.balances[from_address] < amount:
            self.log_event("Transfer Failed", f"Insufficient funds for {from_address}")
            return False
        if to_address not in self.balances:
            self.balances[to_address] = 0
        self.balances[from_address] -= amount
        self.balances[to_address] += amount
        self.log_event("Transfer Successful", f"{amount} {self.token_name} transferred from {from_address} to {to_address}")
        return True

    def log_event(self, event_type, message):
        self.events.append((event_type, message))
        print(f"{event_type}: {message}")

