        self.portfolio = {}

    def add_cryptocurrency(self, symbol, quantity):
        if symbol in self.portfolio:
            self.portfolio[symbol] += quantity
        else:
            self.portfolio[symbol] = quantity

    def remove_cryptocurrency(self, symbol, quantity):
        if symbol in self.portfolio:
            if self.portfolio[symbol] >= quantity:
                self.portfolio[symbol] -= quantity
                if self.portfolio[symbol] == 0:
                    del self.portfolio[symbol]
            else:
                raise ValueError("Not enough quantity to remove")
        else:
            raise KeyError("Cryptocurrency not found in portfolio")

    def update_cryptocurrency(self, symbol, quantity):
        self.remove_cryptocurrency(symbol, self.portfolio[symbol])
        self.add_cryptocurrency(symbol, quantity)

    def get_total_value(self):
        url = "https://api.coingecko.com/api/v3/simple/price"
        params = {
            "ids": ",".join(self.portfolio.keys()),
            "vs_currencies": "usd"
        }
