import requests

class PaymentSystemAPIManager:
    def __init__(self, base_url):
        self.base_url = base_url

    def process_payment_requests(self, payment_requests):
        valid_requests = [request for request in payment_requests if self.is_valid_request(request)]
        response_data = [self.send_request(request) for request in valid_requests]
        return response_data

    def is_valid_request(self, request):
        # Example criteria: request must have a valid amount and currency
        return 'amount' in request and 'currency' in request and request['amount'] > 0

    def send_request(self, request):
        url = f"{self.base_url}/payments"
        response = requests.post(url, json=request)
        return response.json()

