class TaxDeduction:
    def __init__(self):
        self.deductions = {}

    def add_deduction(self, category, amount):
        if category in self.deductions:
            self.deductions[category] += amount
        else:
            self.deductions[category] = amount

    def remove_deduction(self, category, amount):
        if category in self.deductions:
            if self.deductions[category] >= amount:
                self.deductions[category] -= amount
                if self.deductions[category] == 0:
                    del self.deductions[category]
            else:
                raise ValueError("Amount to remove exceeds current deduction")
        else:
            raise KeyError("Category not found")

    def modify_deduction(self, category, new_amount):
        if category in self.deductions:
            self.deductions[category] = new_amount
        else:
            raise KeyError("Category not found")

    def total_deductions(self):
        return sum(self.deductions.values())

    def generate_report(self):
        report = "Tax Deduction Report:\n"
        for category, amount in self.deductions.items():
            report += f"{category}: ${amount:.2f}\n"
        report += f"Total Deductions: ${self.total_deductions():.2f}"
        return report

