import heapq

class RiskScoreManager:
    def __init__(self):
        self.risk_scores = {}
        self.high_risk_queue = []

    def add_transaction(self, transaction_id, risk_score):
        if transaction_id in self.risk_scores:
            self.update_transaction(transaction_id, risk_score)
        else:
            self.risk_scores[transaction_id] = risk_score
            heapq.heappush(self.high_risk_queue, (-risk_score, transaction_id))

    def update_transaction(self, transaction_id, new_risk_score):
        if transaction_id in self.risk_scores:
            old_risk_score = self.risk_scores[transaction_id]
            self.risk_scores[transaction_id] = new_risk_score
            if new_risk_score > old_risk_score:
                self.high_risk_queue.remove((-old_risk_score, transaction_id))
                heapq.heappush(self.high_risk_queue, (-new_risk_score, transaction_id))
                heapq.heapify(self.high_risk_queue)

    def get_risk_score(self, transaction_id):
        return self.risk_scores.get(transaction_id, None)

    def get_high_risk_transactions(self, n=10):
        return heapq.nsmallest(n, self.high_risk_queue, key=lambda x: x[0])

# Example usage
risk_manager = RiskScoreManager()
risk_manager.add_transaction('TXN1', 5)
risk_manager.add_transaction('TXN2', 10)
risk_manager.update_transaction('TXN1', 7)
print(risk_manager.get_risk_score('TXN1'))  # Output: 7
print(risk_manager.get_high_risk_transactions())  # Output: [(-10, 'TXN2'), (-7, 'TXN1')]

