import heapq

class PaymentTransaction:
    def __init__(self, transaction_id, amount, priority):
        self.transaction_id = transaction_id
        self.amount = amount
        self.priority = priority

    def __lt__(self, other):
        return self.priority < other.priority

class PaymentQueue:
    def __init__(self):
        self.queue = []
        self.transaction_map = {}

    def enqueue(self, transaction):
        if transaction.transaction_id in self.transaction_map:
            raise ValueError("Transaction ID already exists")
        heapq.heappush(self.queue, transaction)
        self.transaction_map[transaction.transaction_id] = transaction

    def dequeue(self):
        if not self.queue:
            raise ValueError("Queue is empty")
        transaction = heapq.heappop(self.queue)
        del self.transaction_map[transaction.transaction_id]
        return transaction

    def update_transaction_status(self, transaction_id, new_status):
        if transaction_id not in self.transaction_map:
            raise ValueError("Transaction ID not found")
        self.transaction_map[transaction_id].status = new_status

    def get_transaction(self, transaction_id):
        if transaction_id not in self.transaction_map:
            raise ValueError("Transaction ID not found")
        return self.transaction_map[transaction_id]

# Example usage
