import threading
from collections import deque

class ATMTransactionQueue:
    def __init__(self):
        self.queue = deque()
        self.lock = threading.Lock()

    def enqueue(self, transaction):
        with self.lock:
            self.queue.append(transaction)

    def dequeue(self):
        with self.lock:
            if self.queue:
                return self.queue.popleft()
            return None

    def get_status(self):
        with self.lock:
            return len(self.queue)

    def enqueue_urgent(self, transaction):
        with self.lock:
            self.queue.appendleft(transaction)

# Example usage:
