import pandas as pd

class ActuarialReservesCalculator:
    def __init__(self):
        self.claim_data = pd.DataFrame()

    def load_claim_data(self, file_path):
        self.claim_data = pd.read_csv(file_path)

    def calculate_ldfs(self):
        # Assuming claim_data has 'DevelopmentYear' and 'ClaimAmount' columns
        ldf = self.claim_data.groupby('DevelopmentYear')['ClaimAmount'].sum().pct_change()
        ldf = ldf.fillna(1)  # Fill NaN values with 1 to avoid division by zero
        return ldf

    def estimate_reserves(self):
        if self.claim_data.empty:
            raise ValueError("Claim data not loaded. Please load claim data using load_claim_data method.")

        ldfs = self.calculate_ldfs()
        # Calculate the reserve by applying LDFs to the most recent year's claims
        most_recent_year = self.claim_data['DevelopmentYear'].max()
        most_recent_claims = self.claim_data[self.claim_data['DevelopmentYear'] == most_recent_year]['ClaimAmount'].sum()
        reserves = most_recent_claims / ldfs.iloc[-1]
        return reserves

class FraudDetector:
    def __init__(self):
        self.transactions = []
        self.high_value_threshold = 1000
        self.repeat_threshold = 5

    def add_transaction(self, transaction):
        self.transactions.append(transaction)

    def check_fraudulent_patterns(self):
        fraudulent_transactions = []
        for i, transaction in enumerate(self.transactions):
            if transaction['amount'] > self.high_value_threshold:
                fraudulent_transactions.append(transaction)
            for j in range(i + 1, len(self.transactions)):
                if self.transactions[j]['amount'] == transaction['amount'] and abs(self.transactions[j]['timestamp'] - transaction['timestamp']) < self.repeat_threshold:
                    fraudulent_transactions.append(transaction)
                    break
        return fraudulent_transactions

