import hashlib
import os
from datetime import datetime

class Document:
    def __init__(self, document_id, document_type, file_path, max_size=10*1024*1024):
        self.document_id = document_id
        self.document_type = document_type
        self.file_path = file_path
        self.max_size = max_size
        self.upload_date = datetime.now()
        self.validate_document()

    def validate_document(self):
        if not self.file_path:
            raise ValueError("File path cannot be empty")
        if not os.path.exists(self.file_path):
            raise FileNotFoundError(f"File not found: {self.file_path}")
        if os.path.getsize(self.file_path) > self.max_size:
            raise ValueError(f"File size exceeds the limit of {self.max_size} bytes")
        if not self.document_type in ['pdf', 'docx', 'jpg', 'png']:
            raise ValueError("Unsupported document type")

    def get_document_hash(self):
        hasher = hashlib.sha256()
        with open(self.file_path, 'rb') as f:
            buf = f.read(65536)
            while buf:
                hasher.update(buf)
                buf = f.read(65536)
        return hasher.hexdigest()

    def __repr__(self):
        return f"Document(document_id={self.document_id}, document_type={self.document_type}, file_path={self.file_path}, upload_date={self.upload_date})"

class DocumentManager:
    def __init__(self):
        self.documents = {}

    def add_document(self, document_id, document_type, file_path):
        if document_id in self.documents:
            raise ValueError(f"Document with id {document_id} already exists")
        self.documents[document_id] = Document(document_id, document_type, file_path)
        return self.documents[document_id]

    def update_document(self, document_id, document_type=None, file_path=None):
        if document_id not in self.documents:
            raise ValueError(f"Document with id {document_id} does not exist")
        doc = self.documents[document_id]
        if document_type:
            doc.document_type = document_type
        if file_path:
            doc.file_path = file_path
            doc.validate_document()
        doc.upload_date = datetime.now()
        return doc

    def delete_document(self, document_id):
        if document_id not in self.documents:
            raise ValueError(f"Document with id {document_id} does not exist")
        del self.documents[document_id]

    def get_document(self, document_id):
        if document_id not in self.documents:
            raise ValueError(f"Document with id {document_id} does not exist")
        return self.documents[document_id]

    def get_document_hash(self, document_id):
        if document_id not in self.documents:
            raise ValueError(f"Document with id {document_id} does not exist")
        return self.documents[document_id].get_document_hash()

    def __repr__(self):
        return f"DocumentManager(documents={list(self.documents.values())})"

