import inspect

class FraudMeta(type):
    def __new__(cls, name, bases, dct):
        # Enforce attribute constraints
        for attr_name, attr_value in dct.items():
            if not isinstance(attr_value, (int, str, float, bool)):
                raise TypeError(f"Attribute '{attr_name}' must be of type int, str, float, or bool")

        # Enforce method constraints
        for method_name, method_value in dct.items():
            if inspect.isfunction(method_value):
                if method_name.startswith('detect_') or method_name.startswith('prevent_'):
                    if not method_value.__doc__:
                        raise ValueError(f"Method '{method_name}' must have a docstring")
                    if 'raise' not in method_value.__doc__.lower():
                        raise ValueError(f"Method '{method_name}' must raise an exception if a fraud is detected or prevented")

        return super().__new__(cls, name, bases, dct)

