class RiskAssessment:
    def __init__(self, policy_type, claim_history, customer_demographics):
        self.policy_type = policy_type
        self.claim_history = claim_history
        self.customer_demographics = customer_demographics

    def calculate_risk_score(self):
        risk_score = 0
        if self.policy_type == "Auto":
            risk_score += 10
        elif self.policy_type == "Home":
            risk_score += 15
        elif self.policy_type == "Life":
            risk_score += 20

        if self.claim_history:
            risk_score += 5 * len(self.claim_history)

        if self.customer_demographics['age'] < 30:
            risk_score += 5
        elif self.customer_demographics['age'] >= 60:
            risk_score += 10

        if self.customer_demographics['income'] < 50000:
            risk_score += 5
        elif self.customer_demographics['income'] >= 100000:
            risk_score += 10

        return risk_score

    def generate_risk_report(self):
        risk_score = self.calculate_risk_score()
        report = f"Policy Type: {self.policy_type}\n"
        report += f"Claim History: {len(self.claim_history)} claims\n"
        report += f"Customer Demographics: Age {self.customer_demographics['age']}, Income {self.customer_demographics['income']}\n"
        report += f"Risk Score: {risk_score}\n"
        return report

