class TradingPlatform:
    def __init__(self, orders):
        self.orders = orders

    def process_orders(self):
        # Filter out invalid or duplicate orders using list comprehensions
        valid_orders = [
            order for i, order in enumerate(self.orders)
            if self.is_valid_order(order) and not self.is_duplicate_order(order, i)
        ]
        return valid_orders

    def is_valid_order(self, order):
        # Example criteria for a valid order: non-negative quantity and positive price
        return order['quantity'] >= 0 and order['price'] > 0

    def is_duplicate_order(self, order, index):
        # Check for duplicate orders based on order ID
        return any(self.orders[j]['order_id'] == order['order_id'] and j != index for j in range(len(self.orders)))

