class AccountMeta(type):
    def __new__(cls, name, bases, attrs):
        # Enforce account type validation
        if 'account_type' not in attrs:
            raise ValueError("Account type must be specified")
        if attrs['account_type'] not in ['savings', 'checking', 'credit']:
            raise ValueError("Invalid account type")

        # Enforce minimum balance
        if 'minimum_balance' not in attrs:
            raise ValueError("Minimum balance must be specified")
        if attrs['minimum_balance'] < 0:
            raise ValueError("Minimum balance cannot be negative")

        # Enforce transaction limits
        if 'transaction_limit' not in attrs:
            raise ValueError("Transaction limit must be specified")
        if attrs['transaction_limit'] < 0:
            raise ValueError("Transaction limit cannot be negative")

        return super().__new__(cls, name, bases, attrs)

class Account(metaclass=AccountMeta):
    def __init__(self, account_number, owner, account_type, minimum_balance, transaction_limit):
        self.account_number = account_number
        self.owner = owner
        self.account_type = account_type
        self.balance = 0
        self.minimum_balance = minimum_balance
        self.transaction_limit = transaction_limit

    def deposit(self, amount):
        if amount < 0:
            raise ValueError("Deposit amount cannot be negative")
        self.balance += amount
        if self.balance < self.minimum_balance:
            raise ValueError("Balance cannot go below minimum balance")

    def withdraw(self, amount):
        if amount < 0:
            raise ValueError("Withdrawal amount cannot be negative")
        if amount > self.balance:
            raise ValueError("Insufficient funds")
        if amount > self.transaction_limit:
            raise ValueError("Transaction exceeds transaction limit")
        self.balance -= amount

