def average_loss(num_catastrophes, loss_data):
    total_loss = 0
    for i in range(num_catastrophes):
        total_loss += loss_data[i]
    average = total_loss / num_catastrophes
    return average

class LoanToValueRatio:
    def __init__(self, loan_amount: float, property_value: float):
        self.loan_amount = loan_amount
        self.property_value = property_value

    def calculate_ltv(self) -> float:
        if self.property_value <= 0:
            raise ValueError("Property value must be greater than 0")
        return self.loan_amount / self.property_value

    def update_loan_amount(self, new_loan_amount: float):
        self.loan_amount = new_loan_amount

    def update_property_value(self, new_property_value: float):
        if new_property_value <= 0:
            raise ValueError("Property value must be greater than 0")
        self.property_value = new_property_value

    def validate_ltv(self, max_ltv: float = 0.8) -> bool:
        ltv = self.calculate_ltv()
        return ltv <= max_ltv

