import re

class FungibleTokenManager:
    def __init__(self):
        self.token_balances = {}
        self.transaction_id_pattern = re.compile(r'^[A-Za-z0-9]{32}$')

    def transfer_tokens(self, from_address, to_address, amount, transaction_id):
        if not self.transaction_id_pattern.match(transaction_id):
            raise ValueError("Invalid transaction ID format")

        if from_address not in self.token_balances or self.token_balances[from_address] < amount:
            raise ValueError("Insufficient funds or invalid from address")

        if to_address not in self.token_balances:
            self.token_balances[to_address] = 0

        self.token_balances[from_address] -= amount
        self.token_balances[to_address] += amount
        return True

    def get_balance(self, address):
        return self.token_balances.get(address, 0)

