class PaymentOrchestrator:
    def __init__(self):
        self.payment_events = {}

    def add_event(self, event):
        if event.transaction_id not in self.payment_events:
            self.payment_events[event.transaction_id] = []
        self.payment_events[event.transaction_id].append(event)

    def update_event(self, transaction_id, event_id, new_status):
        if transaction_id in self.payment_events:
            for event in self.payment_events[transaction_id]:
                if event.event_id == event_id:
                    event.status = new_status
                    break

    def remove_event(self, transaction_id, event_id):
        if transaction_id in self.payment_events:
            self.payment_events[transaction_id] = [event for event in self.payment_events[transaction_id] if event.event_id != event_id]

    def get_payment_state(self, transaction_id):
        if transaction_id in self.payment_events:
            return self.payment_events[transaction_id]
        return []

