import weakref

class FundTransfer:
    _pool = weakref.WeakValueDictionary()

    def __new__(cls, *args, **kwargs):
        key = (args, tuple(kwargs.items()))
        if key not in cls._pool:
            cls._pool[key] = super().__new__(cls)
        return cls._pool[key]

    def __init__(self, sender, receiver, amount):
        self.sender = sender
        self.receiver = receiver
        self.amount = amount

    def execute_transfer(self):
        print(f"Transferring {self.amount} from {self.sender} to {self.receiver}")

def create_fund_transfer(sender, receiver, amount):
    return FundTransfer(sender, receiver, amount)

# Example usage
if __name__ == "__main__":
    transfer1 = create_fund_transfer("Alice", "Bob", 100)
    transfer2 = create_fund_transfer("Alice", "Bob", 100)
    transfer3 = create_fund_transfer("Charlie", "David", 200)

    print(transfer1 is transfer2)  # True, demonstrating object pooling
    print(transfer1 is transfer3)  # False, different instances

class PhishingDetector:
    def __init__(self):
        self.keywords = ["login", "account", "bank", "verify", "update", "secure", "password"]

    def add_keyword(self, keyword):
        self.keywords.append(keyword)

    def detect_phishing(self, url):
        for keyword in self.keywords:
            if keyword in url:
                return True
        return False

# Test the PhishingDetector class
