print(detector.detect_phishing("https://www.example.com/login"))  # True
print(detector.detect_phishing("https://www.example.com/about"))   # False

# Add a new keyword
detector.add_keyword("confirm")
print(detector.detect_phishing("https://www.example.com/confirm"))  # True

class Portfolio:
    def __init__(self, name, total_value, investments):
        self.name = name
        self.total_value = total_value
        self.investments = investments

    def add_investment(self, investment_name, number_of_shares, purchase_price_per_share):
        new_investment = {
            'investment_name': investment_name,
            'number_of_shares': number_of_shares,
            'purchase_price_per_share': purchase_price_per_share
        }
        self.investments.append(new_investment)
        self.update_total_value()

    def update_total_value(self):
        self.total_value = sum(
            inv['number_of_shares'] * inv['purchase_price_per_share'] for inv in self.investments
        )

# Example usage:
