print(f"Total Value: {portfolio.total_value}")

import datetime

class SavingsGoalInterface:
    def track_progress(self):
        raise NotImplementedError("Subclasses must implement track_progress method")

    def generate_summary(self):
        raise NotImplementedError("Subclasses must implement generate_summary method")

class SavingsGoalMeta(type):
    def __new__(cls, name, bases, attrs):
        if not all(hasattr(attrs, attr) for attr in ['goal_amount', 'start_date', 'end_date', 'periodic_contribution']):
            raise TypeError("Savings Goal models must have goal_amount, start_date, end_date, and periodic_contribution attributes")
        if not issubclass(attrs['track_progress'], SavingsGoalInterface.track_progress):
            raise TypeError("track_progress method must be implemented from SavingsGoalInterface")
        if not issubclass(attrs['generate_summary'], SavingsGoalInterface.generate_summary):
            raise TypeError("generate_summary method must be implemented from SavingsGoalInterface")
        return super().__new__(cls, name, bases, attrs)

class SavingsGoal(metaclass=SavingsGoalMeta):
    def __init__(self, goal_amount, start_date, end_date, periodic_contribution):
        self.goal_amount = goal_amount
        self.start_date = start_date
        self.end_date = end_date
        self.periodic_contribution = periodic_contribution
        self.current_amount = 0

    def track_progress(self):
        current_date = datetime.datetime.now()
        if current_date >= self.start_date and current_date <= self.end_date:
            self.current_amount += self.periodic_contribution
        return self.current_amount

    def generate_summary(self):
        progress = self.track_progress()
        summary = {
            "goal_amount": self.goal_amount,
            "start_date": self.start_date,
            "end_date": self.end_date,
            "periodic_contribution": self.periodic_contribution,
            "current_amount": progress,
            "progress_percentage": (progress / self.goal_amount) * 100 if self.goal_amount != 0 else 0
        }
        return summary

# Example usage:
savings_goal = SavingsGoal(10000, datetime.date(2023, 1, 1), datetime.date(2023, 12, 31), 100)
print(savings_goal.generate_summary())

class BudgetTracker:
    def __init__(self):
        self.budget_data = {}

    def add_user(self, user_id, initial_budget):
        self.budget_data[user_id] = initial_budget

    def update_budget(self, transactions):
        for transaction in transactions:
            user_id = transaction['user_id']
            amount = transaction['amount']
            category = transaction['category']
            if user_id in self.budget_data:
                if category == 'expense':
                    self.budget_data[user_id] -= amount
                elif category == 'income':
                    self.budget_data[user_id] += amount

    def get_budget(self, user_id):
        return self.budget_data.get(user_id, 0)

from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///loans.db'
db = SQLAlchemy(app)

class Loan(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    loan_id = db.Column(db.String(100), unique=True, nullable=False)
    borrower_name = db.Column(db.String(100), nullable=False)
    loan_amount = db.Column(db.Float, nullable=False)
    status = db.Column(db.String(50), nullable=False, default='Pending')

class ForbearanceRequest(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    loan_id = db.Column(db.String(100), db.ForeignKey('loan.id'), nullable=False)
    request_date = db.Column(db.DateTime, nullable=False)
    status = db.Column(db.String(50), nullable=False, default='Pending')

@app.route('/')
def index():
    loans = Loan.query.all()
    return render_template('index.html', loans=loans)

@app.route('/submit', methods=['POST'])
def submit():
    loan_id = request.form['loan_id']
    borrower_name = request.form['borrower_name']
    loan_amount = float(request.form['loan_amount'])
    new_loan = Loan(loan_id=loan_id, borrower_name=borrower_name, loan_amount=loan_amount)
    db.session.add(new_loan)
    db.session.commit()
    return redirect(url_for('index'))

@app.route('/request_forbearance/<int:loan_id>', methods=['POST'])
def request_forbearance(loan_id):
    loan = Loan.query.get_or_404(loan_id)
    new_request = ForbearanceRequest(loan_id=loan.id, request_date=request.form['request_date'])
    db.session.add(new_request)
    db.session.commit()
    return redirect(url_for('index'))

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)

