class CustomerSupport:
    def __init__(self):
        self.issues = {}

    def report_issue(self, issue_id, description):
        if issue_id in self.issues:
            return "Issue already reported."
        self.issues[issue_id] = {'description': description, 'status': 'Open'}
        return "Issue reported successfully."

    def get_response(self, issue_id):
        if issue_id not in self.issues:
            return "Issue not found."
        issue = self.issues[issue_id]
        if issue['status'] == 'Closed':
            return f"Issue {issue_id} is closed. Response: {issue['response']}"
        return "Response not available yet."

    def check_status(self, issue_id):
        if issue_id not in self.issues:
            return "Issue not found."
        return f"Issue {issue_id} status: {self.issues[issue_id]['status']}"

