import heapq
from collections import defaultdict

class InvestmentManager:
    def __init__(self):
        self.products = defaultdict(int)
        self.priority_queue = []

    def add_product(self, product_id, performance):
        if product_id in self.products:
            self.remove_product(product_id)
        self.products[product_id] = performance
        heapq.heappush(self.priority_queue, (-performance, product_id))

    def remove_product(self, product_id):
        if product_id in self.products:
            del self.products[product_id]
            self.priority_queue = [item for item in self.priority_queue if item[1] != product_id]
            heapq.heapify(self.priority_queue)

    def get_product_performance(self, product_id):
        return self.products.get(product_id, None)

    def get_top_performing_product(self):
        if self.priority_queue:
            return self.priority_queue[0][1]
        return None

# Example usage:
investment_manager = InvestmentManager()
investment_manager.add_product('A123', 0.05)
investment_manager.add_product('B456', 0.03)
investment_manager.add_product('C789', 0.07)

print("Top performing product:", investment_manager.get_top_performing_product())
print("Performance of product A123:", investment_manager.get_product_performance('A123'))
investment_manager.remove_product('A123')
print("Top performing product after removal:", investment_manager.get_top_performing_product())

