import asyncio

class SmartContractInteroperability:
    def __init__(self, contracts):
        self.contracts = contracts

    async def execute_transaction(self, contract_id, transaction_data):
        if contract_id in self.contracts:
            contract = self.contracts[contract_id]
            return await contract.process_transaction(transaction_data)
        else:
            raise ValueError(f"Contract with ID {contract_id} not found")

    async def process_all_transactions(self, transactions):
        tasks = []
        for contract_id, transaction_data in transactions:
            task = asyncio.create_task(self.execute_transaction(contract_id, transaction_data))
            tasks.append(task)
        results = await asyncio.gather(*tasks)
        return results

class SmartContract:
    def __init__(self, name):
        self.name = name

    async def process_transaction(self, data):
        # Simulate transaction processing
        await asyncio.sleep(1)
        return f"Transaction processed by {self.name} with data: {data}"

# Example usage
async def main():
    contracts = {
        "contract1": SmartContract("Contract 1"),
        "contract2": SmartContract("Contract 2")
    }
    interoperability = SmartContractInteroperability(contracts)

    transactions = [
        ("contract1", {"value": 100, "to": "Alice"}),
        ("contract2", {"value": 200, "to": "Bob"})
    ]

    results = await interoperability.process_all_transactions(transactions)
    for result in results:
        print(result)

# Run the example
asyncio.run(main())

