import time
from collections import defaultdict
from heapq import heappop, heappush

class PushNotificationQueue:
    def __init__(self):
        self.users = defaultdict(list)
        self.user_last_activity = {}

    def add_notification(self, user_id, notification, urgency=0):
        if user_id not in self.user_last_activity:
            self.user_last_activity[user_id] = time.time()
        heappush(self.users[user_id], (-urgency, time.time(), notification))

    def get_notifications(self, user_id, max_notifications=5):
        if user_id not in self.user_last_activity:
            return []
        current_time = time.time()
        notifications = []
        while self.users[user_id] and current_time - self.users[user_id][0][1] > 3600:  # Remove expired notifications
            heappop(self.users[user_id])
        while self.users[user_id] and len(notifications) < max_notifications:
            _, _, notification = heappop(self.users[user_id])
            notifications.append(notification)
        return notifications

    def update_user_activity(self, user_id):
        self.user_last_activity[user_id] = time.time()

# Example usage
if __name__ == "__main__":
    queue = PushNotificationQueue()
    queue.add_notification("user1", "Transaction alert: $100.00 debited", urgency=5)
    queue.add_notification("user1", "Monthly savings reminder", urgency=1)
    queue.add_notification("user2", "Low balance alert: $50.00 remaining", urgency=3)
    print(queue.get_notifications("user1"))
    queue.update_user_activity("user1")
    print(queue.get_notifications("user1"))
